INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Nebula Structures · Round 7','Which image was made with AI?','{\"images\":{\"photo\":\"/assets/media/game1/img_6bab7b2c95a7.webp\",\"ai\":\"/assets/media/game1/img_e4b3d0c2c478.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"ai\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Documentary Frame · Round 9','Which image was made with AI?','{\"images\":{\"photo\":\"/assets/media/game1/img_f0aba2e3d3c4.webp\",\"ai\":\"/assets/media/game1/img_cac2675b6be8.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"ai\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Night Sky · Round 11','Which image was made with AI?','{\"images\":{\"photo\":\"/assets/media/game1/img_6ef347d36b58.webp\",\"ai\":\"/assets/media/game1/img_b9e2ae090031.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"ai\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Mountain lake and cabins','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_9c87cf67083d.webp\",\"b\":\"/assets/media/game1/img_c2b6707d8696.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: inkknife_2000 (7.5 million views +), CC BY-SA 2.0, Wikimedia Commons. AI image: Apple Image Playground, Public domain, Wikimedia Commons.\"}','{\"choice\":\"a\"}','Light pouring from a cloud onto the mountain, fairy-tale colours and identical cabins are not realistic; in the real photo the reflections and trees are irregular. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','0-13,14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Snowy canal town','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_d08e0999dfec.webp\",\"b\":\"/assets/media/game1/img_3b8f90cec95b.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Fons Heijnsbroek, CC0, Wikimedia Commons. AI image: Seedream 4.5, CC BY 4.0, Wikimedia Commons.\"}','{\"choice\":\"b\"}','A giant moon, a sky full of stars and storybook buildings would not look this sharp in a real night photo; in the real photo the lights are scattered and the sky is dark. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','0-13,14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Tulip garden','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_8023e1f32a0e.webp\",\"b\":\"/assets/media/game1/img_2b50301e2989.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: ほくなん, Public domain, Wikimedia Commons. AI image: Leonardo AI, Public domain, Wikimedia Commons.\"}','{\"choice\":\"b\"}','Mount Fuji, a pagoda, traditional houses and tulips in one frame: every cliche packed together. The real photo shows an ordinary tulip field and a windmill. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','0-13,14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Crater Marks · Round 8','Which image comes from a verified photo source?','{\"images\":{\"photo\":\"/assets/media/game1/img_6ef347d36b58.webp\",\"ai\":\"/assets/media/game1/img_b9e2ae090031.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"photo\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Before Dawn · Round 10','Which image comes from a verified photo source?','{\"images\":{\"photo\":\"/assets/media/game1/img_20aaed48c421.webp\",\"ai\":\"/assets/media/game1/img_86ae44218f5a.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"photo\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Star Field · Round 12','Which image comes from a verified photo source?','{\"images\":{\"photo\":\"/assets/media/game1/img_6bab7b2c95a7.webp\",\"ai\":\"/assets/media/game1/img_e4b3d0c2c478.webp\"},\"credit\":\"Photo: scikit-image sample data, sourced from NASA; synthetic counterpart: created for this project with OpenAI ImageGen.\",\"action_tip\":\"Whether an image is true and how it was made are two different questions; check the context separately.\",\"options\":[{\"id\":\"photo\",\"text\":\"Source photo\"},{\"id\":\"ai\",\"text\":\"AI-generated\"}]}','{\"choice\":\"photo\"}','An image can look realistic or flawless, but that alone does not prove where it came from. Check the publisher, run a reverse image search and look for Content Credentials or a provenance record if there is one.','all',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Hedgehog','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_7129c2611161.webp\",\"b\":\"/assets/media/game1/img_abda127d7a2d.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Calle Eklund/V-wolf, CC BY-SA 3.0, Wikimedia Commons. AI image: FLUX.1 [schnell]; prompted by Emdosis, Public domain, Wikimedia Commons.\"}','{\"choice\":\"b\"}','In the AI image the spines are too neat and clean and the background is blurred like a studio shot; the real photo has asphalt, dust and natural mess. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Seaside hotel','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_b76a23e90aca.webp\",\"b\":\"/assets/media/game1/img_c828b0b311f7.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Ben Brooksbank, CC BY-SA 2.0, Wikimedia Commons. AI image: Dennis Sylvester Hurd, CC BY 4.0, Wikimedia Commons.\"}','{\"choice\":\"a\"}','The palace-like hotel in the AI image is perfectly lit, like a postcard; the real photo is ordinary, hazy and imperfectly framed. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · River valley','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_223ad69215a5.webp\",\"b\":\"/assets/media/game1/img_e39b762e1a8a.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Daniel Case, CC BY-SA 3.0, Wikimedia Commons. AI image: Imagen 4.0, Public domain, Wikimedia Commons.\"}','{\"choice\":\"b\"}','In the AI image every element (cabin, river, rocks) looks carefully placed and the light falls evenly everywhere; the small mark in the bottom-right corner is also a clue. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Grilled chicken salad','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_b562e563b14f.webp\",\"b\":\"/assets/media/game1/img_a0fc2e87f0e2.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Prayitno / Thank you for (12 millions +) view from Los Angeles, USA, CC BY 2.0, Wikimedia Commons. AI image: Dennis Sylvester Hurd, CC0, Wikimedia Commons.\"}','{\"choice\":\"a\"}','In the AI image the food, drinks and background are over-vivid, like an advert; the real photo shows an ordinary restaurant plate on a paper placemat. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Green apple','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_f28672633d28.webp\",\"b\":\"/assets/media/game1/img_82c293b1a463.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: George Chernilevsky, Public domain, Wikimedia Commons. AI image: Midjourney; prompted by The masketta man, Public domain, Wikimedia Commons.\"}','{\"choice\":\"b\"}','The single apple is softly lit and flawless, like a still-life painting; in the real photo the apples in the basket have spots, bruises and different sizes. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Vegetable chips','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_438080ef7dfd.webp\",\"b\":\"/assets/media/game1/img_a3a6bd2b80e4.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Mx. Granger, CC0, Wikimedia Commons. AI image: Piersey, CC BY 2.0, Wikimedia Commons.\"}','{\"choice\":\"b\"}','In the AI image the colours are too bright and the ingredients around the bowl are crowded for no reason; the real close-up has natural oil shine and broken pieces. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','14-18,19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Chocolate donut','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_080bd6ab72c0.webp\",\"b\":\"/assets/media/game1/img_2c56bb7a5049.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Kiran Foster from no fixed abode, New Zealand, CC BY 2.0, Wikimedia Commons. AI image: Bango Renders, CC0, Wikimedia Commons.\"}','{\"choice\":\"a\"}','Both look real. In the AI image the sprinkles are scattered too evenly and the light is flawless, like a studio advert; with so few clues, checking the source is a must. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Dumpling soup','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_55e6f8d4532f.webp\",\"b\":\"/assets/media/game1/img_db73d84555b2.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: NeoBatfreak, CC BY-SA 4.0, Wikimedia Commons. AI image: Author: Perchance AI; prompted by John Doe, Public domain, Wikimedia Commons.\"}','{\"choice\":\"a\"}','The AI image copies an ordinary phone photo; the dumplings and the soup surface are a bit too smooth. When images are this realistic, research the source instead of trusting your eyes. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Gift package','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_bba9b7ce25f2.webp\",\"b\":\"/assets/media/game1/img_7e2071fa2e7c.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Loneshieling, CC BY-SA 4.0, Wikimedia Commons. AI image: chatgpt, Public domain, Wikimedia Commons.\"}','{\"choice\":\"a\"}','Even the \"badly wrapped\" gift in the AI image is too neat: the tape edges and polka dots repeat perfectly. In the real photo the ribbon is a mess and the light is dim. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Mountain lake view','Which image is a real photo?','{\"images\":{\"a\":\"/assets/media/game1/img_af530415fbb6.webp\",\"b\":\"/assets/media/game1/img_c358ee48714b.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Frankemann, CC BY-SA 4.0, Wikimedia Commons. AI image: Gemini, Public domain, Wikimedia Commons.\"}','{\"choice\":\"b\"}','Both look like real landscape photos. In the AI image the ridges and lake colour are postcard-perfect; in the real photo the snow, shadows and mist are uneven. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (1,'ai','Web image · Beach huts','Which image was made with AI?','{\"images\":{\"a\":\"/assets/media/game1/img_0d72ffd6b9ad.webp\",\"b\":\"/assets/media/game1/img_726373476d0b.webp\"},\"options\":[{\"id\":\"a\",\"text\":\"Image A\"},{\"id\":\"b\",\"text\":\"Image B\"}],\"credit\":\"Real photo: Gzzz, CC BY-SA 3.0, Wikimedia Commons. AI image: gemini, Public domain, Wikimedia Commons.\"}','{\"choice\":\"a\"}','The AI image copies a busy beach photo very well, but the writing on the signs is unreadable and the huts are almost identical. Zooming in on text is a good tip. To be sure, find the source: do a reverse image search and check the first publisher and any Content Credentials.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Your bank account is closing','Look at this email. Is it fake or trustworthy?','{\"sender\":\"security@yourbank-verify.example\",\"subject\":\"Your account will be suspended\",\"body\":\"Dear customer, your account will be closed within 10 minutes. Verify your password now.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}]}','{\"choice\":\"s2\"}','The message rushes you with a 10-minute deadline and asks for your password. Banks never ask for your password by email. Do not click the link; check your bank\'s own app.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Homework reminder','Look at this email. Is it fake or trustworthy?','{\"sender\":\"teacher@lessons.example\",\"subject\":\"Homework reminder\",\"body\":\"Remember to come to class on time for tomorrow\'s presentation. There is no link attached.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}]}','{\"choice\":\"s1\"}','The message only reminds you about tomorrow\'s presentation. There is no link and it does not ask for a password or any information. If you ever see a strange request, ask your teacher yourself.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Password request from IT','You received this email. Is it fake or trustworthy?','{\"sender\":\"support@account-recovery.example\",\"subject\":\"Your password has expired\",\"body\":\"This is the IT team. Please reply to this email and write your password to us.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: a message trying to trick you\"},{\"id\":\"s2\",\"text\":\"Trustworthy: a normal, safe message\"}]}','{\"choice\":\"s1\"}','The message asks you to reply with your password. A real support team never asks for your password. Do not reply; contact the support team yourself.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Request for a verification code','Look at this email. Is it fake or trustworthy?','{\"sender\":\"verify@code-share.example\",\"subject\":\"Protect your account\",\"body\":\"If you do not share the verification code you just received with us, your account will be closed.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}]}','{\"choice\":\"s2\"}','The message asks for the code sent to your phone and threatens to close your account. Whoever gets this code can get into your account. Never share the code with anyone.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Shared salary spreadsheet','Look at this email. Do you think it is trustworthy?','{\"sender\":\"collab@file-sharing.example\",\"subject\":\"Salary spreadsheet shared with you\",\"body\":\"To view the document, enter your work email password in this form.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: a message trying to trick you\"},{\"id\":\"s2\",\"text\":\"Trustworthy: a normal, safe message\"}]}','{\"choice\":\"s1\"}','You are asked to type your password into a form to see the document. The form is not on the company\'s own site. Do not use the link; open the file system yourself and check.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Meeting room changed','Look at this email. Is it fake or trustworthy?','{\"sender\":\"calendar@company.example\",\"subject\":\"Room change\",\"body\":\"The meeting has moved to Room B. It has also been updated in the company calendar; you do not need to sign in to anything.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: a message trying to trick you\"},{\"id\":\"s2\",\"text\":\"Trustworthy: a normal, safe message\"}]}','{\"choice\":\"s2\"}','The message only says the room has changed and asks you for nothing. You can check the same information in the company\'s own calendar. That is why it is trustworthy.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Unheard voicemail','Look at this email. Do you think it is trustworthy?','{\"sender\":\"alerts@voice-message.example\",\"subject\":\"Unheard message\",\"body\":\"To listen to the recording, open the attached HTML file and sign in with your work account.\",\"preview\":\"Link preview: sample.example (no real link opens).\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}]}','{\"choice\":\"s2\"}','You are asked to sign in through an attached file to play a voice message. You never need a password to listen to audio; the file is there to steal it. Do not open it; check your messages in the app you know.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Problem with your school account','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"help@campus-portal.example\",\"subject\":\"Problem with your student account\",\"body\":\"Your account needs an update. To prove who you are, send your password to this address.\",\"preview\":\"https://campus-portal.example/verify\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: a message trying to trick you\"},{\"id\":\"s2\",\"text\":\"Trustworthy: a normal, safe message\"}],\"review_note\":\"These examples are made up. \'Trustworthy\' does not mean we really checked the sender.\"}','{\"choice\":\"s1\"}','The message asks you to send your password to fix your account. The school system never asks for your password by email. Check the school\'s own system or ask the IT office.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Secret transfer request from the boss','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"manager@urgent-transfer.example\",\"subject\":\"Confidential payment - now\",\"body\":\"I\'m in a meeting, don\'t call me. Make an urgent transfer from the company account to the account below and don\'t tell anyone.\",\"preview\":\"Account details are not shown in this example\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}],\"review_note\":\"These examples are made up. \'Trustworthy\' does not mean we really checked the sender.\"}','{\"choice\":\"s2\"}','The message pretends to be your boss, wants secret and urgent money, and tells you not to call. Scammers use this kind of pressure. Do not send money; call your boss on a number you know.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Supplier\'s new bank account','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"invoices@supplier-payment.example\",\"subject\":\"Our new IBAN / bank account number\",\"body\":\"From now on, please pay all invoices into our new bank account. Do not call the person you used to deal with to check.\",\"preview\":\"New IBAN: [sample]\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: a message trying to trick you\"},{\"id\":\"s2\",\"text\":\"Trustworthy: a normal, safe message\"}],\"review_note\":\"These examples are made up. \'Trustworthy\' does not mean we really checked the sender.\"}','{\"choice\":\"s1\"}','A supplier says it changed its bank account and asks you not to call your usual contact. The money could go to a scammer. Call the supplier on a phone number you already know and ask.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Urgent money request from a relative','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"help@urgent-relative.example\",\"subject\":\"My new number, emergency\",\"body\":\"My phone has changed. Don\'t call me right now, just send money quickly; I\'ll explain later.\",\"preview\":\"No link\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}],\"review_note\":\"These examples are made up. \'Trustworthy\' does not mean we really checked the sender.\"}','{\"choice\":\"s2\"}','The message pretends to be a relative, says their number has changed and asks for money right away. Do not send money; call your relative on their old saved number or ask them face to face.','50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Free diamonds gift','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"gift@game-free-diamonds.example\",\"subject\":\"5000 diamonds are ready for your account!\",\"body\":\"Hi player! To get 5000 diamonds sent to your account, type your username and password on the page below. This offer is valid for 1 hour only. Don\'t tell anyone, or the diamonds will be cancelled!\",\"preview\":\"https://diamond-load.example/login\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: it is fine if you only type your username\"},{\"id\":\"s2\",\"text\":\"Trustworthy: the diamonds look just like the ones in the game\"},{\"id\":\"s3\",\"text\":\"Trustworthy: the game company is giving gifts, sign in now\"},{\"id\":\"s4\",\"text\":\"Fake: it asks for your password, rushes you and wants you to keep a secret\"}]}','{\"choice\":\"s4\"}','The message asks for your password, rushes you with 1 hour and says \'don\'t tell anyone\'. No game company asks for your password to give gifts. Do not click the link; show the message to a trusted adult.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','New device sign-in alert','You just signed in to your game on the tablet at home. Then this email arrived. What do you think?','{\"sender\":\"alerts@gamepark.example\",\"subject\":\"New sign-in from a device\",\"body\":\"Hi Danny_Captain, your account was signed in today at 15:42 from a device called \'Tablet - Home\'. If this wasn\'t you, change your password in the game under Settings > Security. This email will never ask for your password or a code.\",\"preview\":\"No link.\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: having no link means it is a hidden trap\"},{\"id\":\"s2\",\"text\":\"Trustworthy: you signed in, there is no link and it asks for nothing\"},{\"id\":\"s3\",\"text\":\"Trustworthy: just reply and send your password\"},{\"id\":\"s4\",\"text\":\"Fake: every sign-in alert is a trap, so reply with your password\"}]}','{\"choice\":\"s2\"}','The sign-in time and device match the sign-in you just made. There is no link and it does not ask for any information. If you ever see a sign-in you don\'t recognise, change your password inside the game.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Your channel will be deleted','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"copyright-team@vidyo-support-center.example\",\"subject\":\"Your channel will be deleted in 24 hours!\",\"body\":\"Music used without permission was found in your video. To stop your channel being deleted, open the attached appeal_form.exe file and sign in with your account details. Don\'t tell your family, it will slow things down.\",\"preview\":\"Attachment: appeal_form.exe\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: it scares you, wants you to open an .exe file and asks for your account details\"},{\"id\":\"s2\",\"text\":\"Trustworthy: music warnings come like this, fill in the form\"},{\"id\":\"s3\",\"text\":\"Trustworthy: open the file first and see if it has a virus\"},{\"id\":\"s4\",\"text\":\"Trustworthy: it is fine if you open the file on a school computer\"}]}','{\"choice\":\"s1\"}','The attached file ends in .exe; it is not a form but a program that runs. The message scares you and asks you to hide it from your family. Do not open the file; show the message to your family.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','A friend asks for your vote','Read this email carefully. Which answer is right?','{\"sender\":\"emma.wilson@mychat.example\",\"subject\":\"Please vote for me in the contest\",\"body\":\"Hi! I\'m in an art contest, please vote for me. Open the link, type your phone number, then send me the 6-digit code you get so your vote counts. There\'s not much time left, I need it now!\",\"preview\":\"https://art-contest-vote.example/vote\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: you can type your number as long as you don\'t send the code\"},{\"id\":\"s2\",\"text\":\"Fake: Emma\'s account may be stolen; don\'t give the code, ask her another way\"},{\"id\":\"s3\",\"text\":\"Trustworthy: Emma is your friend, you should help her\"},{\"id\":\"s4\",\"text\":\"Trustworthy: it is fine if you send the code to Emma privately\"}]}','{\"choice\":\"s2\"}','The code sent to your phone is the key to your account; do not give it out even if a friend asks. Emma\'s account may have been stolen. Ask Emma face to face or by phone.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Practice exam results','Read this email carefully. Which answer is right?','{\"sender\":\"results@testing-center.example\",\"subject\":\"Your practice exam results are out\",\"body\":\"Dear candidate, your results for the October 12 practice exam are out. To see your result, sign in to the candidate app as usual, or type the candidate website address yourself. For your safety, this email has no links or attachments, and we will never ask for your password.\",\"preview\":\"No link.\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: it names the organisation, so it must be a copy\"},{\"id\":\"s2\",\"text\":\"Trustworthy: it asks for nothing; check your result in the app you know\"},{\"id\":\"s3\",\"text\":\"Fake: if there is no link, the goal is to learn my email address\"},{\"id\":\"s4\",\"text\":\"Trustworthy: reply with your national ID number and they will send your result\"}]}','{\"choice\":\"s2\"}','The message only gives information; there is no link or attachment. It sends you to the app you always use. Still, do not reply with any information; check your result in the app.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Verified badge offer','Read this email carefully. Which answer is right?','{\"sender\":\"verify@socialnet-verify-center.example\",\"subject\":\"Your account was selected for a verified badge\",\"body\":\"Congratulations! Thanks to your follower count, your account can get a verified badge. To claim it within 48 hours, enter your username, password and the verification code sent to your phone in the form below. If time runs out, you lose your chance.\",\"preview\":\"https://badge-apply.example/form\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: if your friends applied too, it is fine\"},{\"id\":\"s2\",\"text\":\"Trustworthy: platforms can ask for your password for a badge\"},{\"id\":\"s3\",\"text\":\"Fake: it asks for your password and code, and the address is not the platform\'s\"},{\"id\":\"s4\",\"text\":\"Trustworthy: you can enter only your password and skip the code\"}]}','{\"choice\":\"s3\"}','The message asks for your password and the code sent to your phone together; whoever has both can get into your account. The sender address is not the platform\'s own. For a badge, check only the app\'s own settings.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Traffic fine discount','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"fine-notice@traffic-payment-center.example\",\"subject\":\"Unpaid fine: 50% off if paid within 24 hours\",\"body\":\"Dear vehicle owner, a $125 traffic fine has been issued for your licence plate. If you pay within 24 hours, you get 50% off. You can pay by entering your card details on the page below. When time runs out, debt collection (legal action) will start against you.\",\"preview\":\"https://fine-pay.example/payment\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: the discount ends soon, pay now\"},{\"id\":\"s2\",\"text\":\"Trustworthy: it reached the wrong person, reply and let them know\"},{\"id\":\"s3\",\"text\":\"Trustworthy: if you pay with a virtual card, there is no risk\"},{\"id\":\"s4\",\"text\":\"Fake: fines are not paid through a card link; check your fines on the official site yourself\"}]}','{\"choice\":\"s4\"}','It does not show your licence plate, rushes you with 24 hours and wants your card details on a strange site. The government does not collect fines through links like this. Type the official government portal address yourself and check your fines there.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Payslip ready notice','Read this email carefully. Which answer is right?','{\"sender\":\"payroll@mycompany.example\",\"subject\":\"Your October payslip is ready\",\"body\":\"Hello, your October payslip has been uploaded to the HR site. To see it, open the site from its usual saved address. This email has no attachment or link; payslips are never sent by email. For questions, call HR on extension 2100.\",\"preview\":\"No link.\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: it is strange to give information without a link\"},{\"id\":\"s2\",\"text\":\"Trustworthy: an expected message; open the HR site from its saved address\"},{\"id\":\"s3\",\"text\":\"Trustworthy: reply now and ask for the payslip by email\"},{\"id\":\"s4\",\"text\":\"Fake: salary emails are always traps, delete it\"}]}','{\"choice\":\"s2\"}','The message comes from the company\'s own address at the expected time. There is no link or attachment and it asks for nothing. Open the HR site from its usual saved address to see your payslip.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','System maintenance notice','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"it@company-notice.example\",\"subject\":\"Planned maintenance\",\"body\":\"The system will be down for maintenance on Saturday from 2:00 to 3:00 AM. This email does not ask for a password or code.\",\"preview\":\"No link\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: a normal, safe message\"},{\"id\":\"s2\",\"text\":\"Fake: a message trying to trick you\"}],\"review_note\":\"These examples are made up. \'Trustworthy\' does not mean we really checked the sender.\"}','{\"choice\":\"s1\"}','The message only announces the maintenance time. There is no link and it does not ask for a password or code. If you want to be sure, check the company\'s announcements page yourself.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Internship offer with no interview','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"hr.careers@intern-opportunity.example\",\"subject\":\"Summer internship accepted: send your documents today\",\"body\":\"Hi, your application has been accepted! To complete your registration, send photos of the front and back of your ID, photos of the front and back of your bank card, and a $25 registration fee today. The fee will be refunded with your first paycheck. No interview needed.\",\"preview\":\"https://internship-signup.example/upload-documents\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: you can send just your ID photo before paying\"},{\"id\":\"s2\",\"text\":\"Fake: only because of the web address; asking for a fee and documents is normal\"},{\"id\":\"s3\",\"text\":\"Fake: no interview, and it asks for money and photos of your card\"},{\"id\":\"s4\",\"text\":\"Trustworthy: internships ask for ID, upload the documents\"}]}','{\"choice\":\"s3\"}','Real employers do not charge for internships or ask for photos of your bank card. Someone could open accounts in your name using photos of your ID. Research the company yourself and do not send any documents.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Trade offer for a game item','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"trade@gamemarket-secure.example\",\"subject\":\"Someone offered $300 for an item in your inventory\",\"body\":\"A player offered $300 for the \'Golden Dragon Shield\' in your inventory. To confirm the sale, sign in with your game market account using the link below. The offer expires in 30 minutes.\",\"preview\":\"https://gamemarket.example.trade-confirm.example/login\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: the link starts with gamemarket.example, so sign in\"},{\"id\":\"s2\",\"text\":\"Trustworthy: the only issue is the high price; the link is safe\"},{\"id\":\"s3\",\"text\":\"Trustworthy: it is fine if you sign in and change your password afterwards\"},{\"id\":\"s4\",\"text\":\"Fake: the real site is trade-confirm.example at the end, not the game market\"}]}','{\"choice\":\"s4\"}','Read the web address from the end: the real site is trade-confirm.example, not the game market. The \'gamemarket\' at the start is there to fool you. Check offers only by opening the app yourself.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Leaked answer key','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"sharing.group@classmate.example\",\"subject\":\"The practice exam answer key leaked!\",\"body\":\"We\'ve got the answer key for tomorrow\'s practice exam. Open the attached archive, the password is 2024. It opens when you run the answers.pdf.scr file inside. Don\'t spread it, it will be deleted soon.\",\"preview\":\"Attachment: answer_key.zip (password-protected)\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: sharing answers is wrong, but the file is safe\"},{\"id\":\"s2\",\"text\":\"Trustworthy: it is a PDF file, so it is harmless\"},{\"id\":\"s3\",\"text\":\"Fake: a password-protected zip cannot be scanned, and .pdf.scr is really a program\"},{\"id\":\"s4\",\"text\":\"Trustworthy: it is fine if you open the zip and just look inside\"}]}','{\"choice\":\"s3\"}','The file name ends in .pdf.scr; it is not a PDF but a program that runs. A password-protected zip slips past antivirus checks. Do not open the file; delete it.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Bonus meeting invitation','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"calendar-noreply@meeting-invite.example\",\"subject\":\"Invitation: Year-End Bonus and Pay Rise Meeting\",\"body\":\"HR has added this meeting to your calendar. Before joining, confirm your attendance by signing in to your company account with the \'Join invitation\' button. Invitations not confirmed within 2 hours will be cancelled and the meeting postponed.\",\"preview\":\"https://meeting-invite.example/sso/company-login\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: it comes from outside the company and leads to a fake sign-in page\"},{\"id\":\"s2\",\"text\":\"Trustworthy: if it was added to your calendar by itself, it came from the company\"},{\"id\":\"s3\",\"text\":\"Trustworthy: the topic is a bonus, but the sign-in page is safe\"},{\"id\":\"s4\",\"text\":\"Trustworthy: links in calendar invitations are checked in advance\"}]}','{\"choice\":\"s1\"}','Showing up in your calendar does not make it safe; outsiders can add invitations too. The sender is outside the company and wants your company password. Ask HR on a phone number you know.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Landlord wants a deposit before a viewing','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"landlord.mark@my-mailbox.example\",\"subject\":\"The flat is still available, a deposit will hold it\",\"body\":\"Hi, I\'m abroad so I can\'t show you the flat, but I can send the key by courier. Three other people are interested; if you pay the $500 deposit into my IBAN / bank account today, I\'ll take the listing down. I\'ve attached a photo of my ID so you can trust me.\",\"preview\":\"Attachment: id_photo.jpg\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: he sent a photo of his ID, so he is honest\"},{\"id\":\"s2\",\"text\":\"Fake: wants money without a viewing, rushes you and will send the key by courier\"},{\"id\":\"s3\",\"text\":\"Trustworthy: if the name on the ID matches the account owner, you can pay\"},{\"id\":\"s4\",\"text\":\"Trustworthy: you can pay half now and the rest later\"}]}','{\"choice\":\"s2\"}','The landlord won\'t show the flat, rushes you and says the key will be sent by courier. The ID photo may be stolen. Never send a deposit (advance payment) before seeing the place and signing a contract.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Job offer document','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"careers@talent-hunter.example\",\"subject\":\"Details of the position you applied for\",\"body\":\"Hello, your CV caught our interest. You can find the salary and benefits for the position in the attached document. Because the document is protected, after opening it you need to click \'Enable Content\' in the yellow bar at the top.\",\"preview\":\"Attachment: Position_Details.docm\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: job offers usually come as protected documents\"},{\"id\":\"s2\",\"text\":\"Trustworthy: the company name is missing, but the attachment is safe\"},{\"id\":\"s3\",\"text\":\"Trustworthy: it is fine if you open the document on your phone\"},{\"id\":\"s4\",\"text\":\"Fake: it wants you to click \'Enable Content\' to run hidden commands\"}]}','{\"choice\":\"s4\"}','The file name ends in .docm; this kind of document can hide commands. If you click \'Enable Content\', those commands run. Do not open the attachment; research the company yourself.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Pension bonus increase','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"bonus@pension-payment-support.example\",\"subject\":\"Your pension bonus has been raised to $1,200\",\"body\":\"Dear pensioner, your pension bonus has been updated. To receive the difference in your account, enter your bank name, card number and the code that will be sent to your phone on the page below. Claims not confirmed by the end of business today will be cancelled.\",\"preview\":\"https://pension-bonus.example/confirm\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: bonus increases are announced like this, confirm it\"},{\"id\":\"s2\",\"text\":\"Fake: it asks for your card number and text-message code; call your bank yourself\"},{\"id\":\"s3\",\"text\":\"Trustworthy: it says \'dear pensioner\', so it comes from an official body\"},{\"id\":\"s4\",\"text\":\"Trustworthy: type your card number but not the text-message code\"}]}','{\"choice\":\"s2\"}','Nobody needs your card number or a text-message code to pay money in; these are used to take money out. The sender has nothing to do with your bank. Call the number on the back of your card and ask.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Secret investigation message','Look at the sender, the message and any attachments. Which answer is best?','{\"sender\":\"prosecutor.office@legal-notice-center.example\",\"subject\":\"CONFIDENTIAL: Investigation opened in your name\",\"body\":\"Dear citizen, an account opened in your name has been used for fraud. The investigation is confidential; do not tell your family or your bank. To protect your money, transfer your savings to the safe holding account in the attachment. Otherwise your accounts will be frozen.\",\"preview\":\"Attachment: safe_account_info.pdf\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: the government sends emails about secret investigations\"},{\"id\":\"s2\",\"text\":\"Trustworthy: call the number in the attachment to check, then you can transfer\"},{\"id\":\"s3\",\"text\":\"Fake: no official body ever asks you to move money to a \'safe account\'\"},{\"id\":\"s4\",\"text\":\"Trustworthy: you can transfer just half of your savings first\"}]}','{\"choice\":\"s3\"}','Prosecutors and police never ask you to move your money. Being told to keep it from your family is a big warning sign. Do nothing, tell your family and call the police on the official emergency number.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','File in an old email thread','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"sarah.collins@partnerfirm.example\",\"subject\":\"RE: RE: November shipping plan\",\"body\":\"Hello, following up on our emails, here is the updated list. The file is large, so I sent it as a cloud link; sign in with your company account to open it.\\n\\n> Your message of 03/11: Hi Sarah, we are waiting for the updated list.\",\"preview\":\"https://partnerfirm-share.example/file/sign-in\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: the sender is a real business partner and it continues an old thread\"},{\"id\":\"s2\",\"text\":\"Fake: the sender address is a copy with changed letters\"},{\"id\":\"s3\",\"text\":\"Fake: Sarah\'s account may be stolen; don\'t open the file, call her\"},{\"id\":\"s4\",\"text\":\"Trustworthy: forward the link to your own email first and open it there\"}]}','{\"choice\":\"s3\"}','The address really is Sarah\'s, but her account may have been stolen. The file is not on her company\'s site and it wants your company password. Do not open the link; call Sarah on a number you know.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Permission for a contract app','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"sign@docapprove-pro.example\",\"subject\":\"A contract is waiting for your signature\",\"body\":\"A contract has been sent to you. To view it, allow the \'DocApprove Pro\' app with your company account. You will not be asked for a password; the sign-in page is your company\'s own page.\",\"preview\":\"https://login.office-cloud.example/oauth/consent?app=DocApprove-Pro&scope=Mail.Read,Files.ReadWrite.All,offline_access\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: an app you don\'t know wants lasting access to your email and files\"},{\"id\":\"s2\",\"text\":\"Trustworthy: if you allow it and change your password afterwards, there is no risk\"},{\"id\":\"s3\",\"text\":\"Fake: the sign-in page is fake and the web address is copied\"},{\"id\":\"s4\",\"text\":\"Trustworthy: the link goes to the company\'s real sign-in page and asks for no password\"}]}','{\"choice\":\"s1\"}','The sign-in page is real, but the app asking for permission belongs to the attacker. The end of the link asks for lasting access to read your emails and files. Changing your password does not stop it; never give permission to an app you don\'t know.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Instructions to approve a number on your phone','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"it-migration@mycompany-identity.example\",\"subject\":\"Sign-in approval system changing: today 14:00\",\"body\":\"Today between 14:00 and 14:15 we are moving to a new verification system. If the approval request on your phone asks for a number, enter 47 and approve. Accounts of users who do not approve will be locked after the move.\",\"preview\":\"No link.\",\"options\":[{\"id\":\"s1\",\"text\":\"Trustworthy: there is no link, it is just a system change notice\"},{\"id\":\"s2\",\"text\":\"Trustworthy: if it is 14:00, you can enter 47\"},{\"id\":\"s3\",\"text\":\"Fake: only the sender address is different; the instructions are normal\"},{\"id\":\"s4\",\"text\":\"Fake: whoever gives the number is trying to get into your account; deny it\"}]}','{\"choice\":\"s4\"}','The number on an approval screen appears on the screen of whoever is signing in. Anyone who tells you the number in advance is the attacker trying to get into your account. Deny any approval you did not start and tell IT.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (2,'mail','Passwordless sign-in setup','Check the sender, the message and the link. Is it fake or trustworthy?','{\"sender\":\"security@mycompany.example\",\"subject\":\"Passkey setup: by November 1\",\"body\":\"We are moving company accounts to passwordless sign-in. There is no link in this email; start the setup on your laptop under Settings > Accounts > Security, or from the \'Security\' tile on the company intranet. You will not be asked for a password, code or approval. Questions: extension 4400.\",\"preview\":\"No link.\",\"options\":[{\"id\":\"s1\",\"text\":\"Fake: it uses passwordless sign-in as an excuse to steal your account\"},{\"id\":\"s2\",\"text\":\"Trustworthy: company address, no link; start the setup from your own settings\"},{\"id\":\"s3\",\"text\":\"Fake: it rushes you by giving a deadline\"},{\"id\":\"s4\",\"text\":\"Trustworthy: to speed things up, call the extension and tell them your code\"}]}','{\"choice\":\"s2\"}','The message comes from the company\'s own address, has no link and asks for nothing. A reasonable deadline alone is not a trap. Start the setup from your own settings and never give your code to anyone.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Office Mission 3','Which thing in the office needs action?','{\"scene\":\"office\",\"objects\":[{\"id\":\"chair\",\"label\":\"Chair\",\"emoji\":\"🪑\",\"x\":22,\"y\":18},{\"id\":\"unlocked\",\"label\":\"Unlocked computer left signed in\",\"emoji\":\"💻\",\"x\":50,\"y\":25},{\"id\":\"cup\",\"label\":\"Cup\",\"emoji\":\"🥤\",\"x\":76,\"y\":18},{\"id\":\"folder\",\"label\":\"File folder\",\"emoji\":\"📁\",\"x\":32,\"y\":65},{\"id\":\"plant\",\"label\":\"Plant\",\"emoji\":\"🪴\",\"x\":61,\"y\":63}],\"location\":\"Office\",\"options\":[{\"id\":\"chair\",\"text\":\"Chair\"},{\"id\":\"unlocked\",\"text\":\"Unlocked computer left signed in\"},{\"id\":\"cup\",\"text\":\"Cup\"},{\"id\":\"folder\",\"text\":\"File folder\"},{\"id\":\"plant\",\"text\":\"Plant\"}]}','{\"choice\":\"unlocked\"}','Lock your screen whenever you step away from your computer.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Classroom Mission 6','Which item in the classroom is in the wrong place?','{\"scene\":\"class\",\"objects\":[{\"id\":\"private\",\"label\":\"Private document left open\",\"emoji\":\"📄\",\"x\":22,\"y\":18},{\"id\":\"marker\",\"label\":\"Whiteboard marker\",\"emoji\":\"🖊️\",\"x\":50,\"y\":25},{\"id\":\"board\",\"label\":\"Board\",\"emoji\":\"📋\",\"x\":76,\"y\":18},{\"id\":\"chair\",\"label\":\"Chair\",\"emoji\":\"🪑\",\"x\":32,\"y\":65},{\"id\":\"bag\",\"label\":\"Backpack\",\"emoji\":\"🎒\",\"x\":61,\"y\":63}],\"location\":\"Classroom\",\"options\":[{\"id\":\"private\",\"text\":\"Private document left open\"},{\"id\":\"marker\",\"text\":\"Whiteboard marker\"},{\"id\":\"board\",\"text\":\"Board\"},{\"id\":\"chair\",\"text\":\"Chair\"},{\"id\":\"bag\",\"text\":\"Backpack\"}]}','{\"choice\":\"private\"}','Private information should never be left on an open screen or in shared spaces.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Hotel Mission 9','In the hotel lobby, which device should you be careful with?','{\"scene\":\"hotel\",\"objects\":[{\"id\":\"sofa\",\"label\":\"Sofa\",\"emoji\":\"🛋️\",\"x\":22,\"y\":18},{\"id\":\"coffee\",\"label\":\"Coffee\",\"emoji\":\"☕\",\"x\":50,\"y\":25},{\"id\":\"plant\",\"label\":\"Plant\",\"emoji\":\"🌿\",\"x\":76,\"y\":18},{\"id\":\"bag\",\"label\":\"Suitcase\",\"emoji\":\"🧳\",\"x\":32,\"y\":65},{\"id\":\"charger\",\"label\":\"Unknown USB charging port\",\"emoji\":\"🔌\",\"x\":61,\"y\":63}],\"location\":\"Hotel\",\"options\":[{\"id\":\"sofa\",\"text\":\"Sofa\"},{\"id\":\"coffee\",\"text\":\"Coffee\"},{\"id\":\"plant\",\"text\":\"Plant\"},{\"id\":\"bag\",\"text\":\"Suitcase\"},{\"id\":\"charger\",\"text\":\"Unknown USB charging port\"}]}','{\"choice\":\"charger\"}','Think about the risks before plugging your device into a charging port you don\'t know.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Cafe Mission 12','Which item should you check before paying at the cafe?','{\"scene\":\"cafe\",\"objects\":[{\"id\":\"water\",\"label\":\"Water\",\"emoji\":\"🥛\",\"x\":22,\"y\":18},{\"id\":\"flower\",\"label\":\"Flower\",\"emoji\":\"🌼\",\"x\":50,\"y\":25},{\"id\":\"plate\",\"label\":\"Plate\",\"emoji\":\"🍽️\",\"x\":76,\"y\":18},{\"id\":\"qr\",\"label\":\"QR sticker from an unknown source\",\"emoji\":\"▦\",\"x\":32,\"y\":65},{\"id\":\"menu\",\"label\":\"Menu\",\"emoji\":\"🍽️\",\"x\":61,\"y\":63}],\"location\":\"Cafe\",\"options\":[{\"id\":\"water\",\"text\":\"Water\"},{\"id\":\"flower\",\"text\":\"Flower\"},{\"id\":\"plate\",\"text\":\"Plate\"},{\"id\":\"qr\",\"text\":\"QR sticker from an unknown source\"},{\"id\":\"menu\",\"text\":\"Menu\"}]}','{\"choice\":\"qr\"}','Check where the QR code came from and whether the web address it opens is correct.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Airport Mission 15','While travelling, which connection choice needs extra checking?','{\"scene\":\"hotel\",\"objects\":[{\"id\":\"bag\",\"label\":\"Suitcase\",\"emoji\":\"🧳\",\"x\":22,\"y\":18},{\"id\":\"coffee\",\"label\":\"Coffee\",\"emoji\":\"☕\",\"x\":50,\"y\":25},{\"id\":\"evil-twin\",\"label\":\"Copycat Wi-Fi that looks like the official network\",\"emoji\":\"📶\",\"x\":76,\"y\":18},{\"id\":\"gate\",\"label\":\"Gate screen\",\"emoji\":\"🛫\",\"x\":32,\"y\":65},{\"id\":\"seat\",\"label\":\"Seat\",\"emoji\":\"💺\",\"x\":61,\"y\":63}],\"location\":\"Airport\",\"options\":[{\"id\":\"bag\",\"text\":\"Suitcase\"},{\"id\":\"coffee\",\"text\":\"Coffee\"},{\"id\":\"evil-twin\",\"text\":\"Copycat Wi-Fi that looks like the official network\"},{\"id\":\"gate\",\"text\":\"Gate screen\"},{\"id\":\"seat\",\"text\":\"Seat\"}]}','{\"choice\":\"evil-twin\"}','Attackers can use network names that look like the official one. Check the network name with staff or on an official sign.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Home Mission 18','Which smart home device needs attention?','{\"scene\":\"home\",\"objects\":[{\"id\":\"lamp\",\"label\":\"Lamp\",\"emoji\":\"💡\",\"x\":22,\"y\":18},{\"id\":\"iot-old\",\"label\":\"Camera that no longer gets updates\",\"emoji\":\"📹\",\"x\":50,\"y\":25},{\"id\":\"toy\",\"label\":\"Toy\",\"emoji\":\"🧸\",\"x\":76,\"y\":18},{\"id\":\"plant\",\"label\":\"Plant\",\"emoji\":\"🪴\",\"x\":32,\"y\":65},{\"id\":\"book\",\"label\":\"Book\",\"emoji\":\"📚\",\"x\":61,\"y\":63}],\"location\":\"Home\",\"options\":[{\"id\":\"lamp\",\"text\":\"Lamp\"},{\"id\":\"iot-old\",\"text\":\"Camera that no longer gets updates\"},{\"id\":\"toy\",\"text\":\"Toy\"},{\"id\":\"plant\",\"text\":\"Plant\"},{\"id\":\"book\",\"text\":\"Book\"}]}','{\"choice\":\"iot-old\"}','Internet-connected devices that no longer get updates can be risky. Disconnect it, update it or replace it with a supported product.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Meeting link · 14','There is a security risk on the projector screen in the classroom. Which object should you tap?','{\"scene\":\"class\",\"location\":\"Classroom\",\"objects\":[{\"id\":\"p116ae04\",\"label\":\"Board\",\"emoji\":\"📋\",\"x\":19,\"y\":19},{\"id\":\"pf666dcf\",\"label\":\"Private meeting link shared publicly\",\"emoji\":\"🔗\",\"x\":47,\"y\":25},{\"id\":\"p4df0e49\",\"label\":\"Book\",\"emoji\":\"📚\",\"x\":73,\"y\":18},{\"id\":\"p0dc355a\",\"label\":\"Crayon\",\"emoji\":\"🖍️\",\"x\":31,\"y\":66},{\"id\":\"p5ac16ff\",\"label\":\"Clock\",\"emoji\":\"🕰️\",\"x\":63,\"y\":62}],\"options\":[{\"id\":\"pf666dcf\",\"text\":\"Private meeting link shared publicly\"},{\"id\":\"p116ae04\",\"text\":\"Board\"},{\"id\":\"p4df0e49\",\"text\":\"Book\"},{\"id\":\"p0dc355a\",\"text\":\"Crayon\"},{\"id\":\"p5ac16ff\",\"text\":\"Clock\"}]}','{\"choice\":\"pf666dcf\"}','Do not share private meeting links publicly.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Company backup · 16','There is a security risk on the office desk. Which object should you tap?','{\"scene\":\"office\",\"location\":\"Office\",\"objects\":[{\"id\":\"pa5bbc7a\",\"label\":\"Plant\",\"emoji\":\"🪴\",\"x\":19,\"y\":19},{\"id\":\"p64d3287\",\"label\":\"Phone stand\",\"emoji\":\"📱\",\"x\":47,\"y\":25},{\"id\":\"p1c040de\",\"label\":\"Unencrypted backup drive with sensitive data\",\"emoji\":\"💽\",\"x\":73,\"y\":18},{\"id\":\"p8b66838\",\"label\":\"Mug\",\"emoji\":\"☕\",\"x\":31,\"y\":66},{\"id\":\"pe6a5f9d\",\"label\":\"Keyboard\",\"emoji\":\"⌨️\",\"x\":63,\"y\":62}],\"options\":[{\"id\":\"p1c040de\",\"text\":\"Unencrypted backup drive with sensitive data\"},{\"id\":\"p64d3287\",\"text\":\"Phone stand\"},{\"id\":\"pa5bbc7a\",\"text\":\"Plant\"},{\"id\":\"pe6a5f9d\",\"text\":\"Keyboard\"},{\"id\":\"p8b66838\",\"text\":\"Mug\"}]}','{\"choice\":\"p1c040de\"}','Protect backups: limit who can access them and keep them encrypted.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Home camera · 17','There is a security risk in the living room at home. Which object should you tap?','{\"scene\":\"home\",\"location\":\"Home\",\"objects\":[{\"id\":\"pb8e2030\",\"label\":\"Television\",\"emoji\":\"📺\",\"x\":19,\"y\":19},{\"id\":\"pd6d8f50\",\"label\":\"Cushion\",\"emoji\":\"🛋️\",\"x\":47,\"y\":25},{\"id\":\"p0e99b9d\",\"label\":\"Book\",\"emoji\":\"📖\",\"x\":73,\"y\":18},{\"id\":\"p2c25976\",\"label\":\"Smart camera still using its factory password\",\"emoji\":\"📹\",\"x\":31,\"y\":66},{\"id\":\"p0a4bf58\",\"label\":\"Flower\",\"emoji\":\"🌸\",\"x\":63,\"y\":62}],\"options\":[{\"id\":\"p2c25976\",\"text\":\"Smart camera still using its factory password\"},{\"id\":\"pb8e2030\",\"text\":\"Television\"},{\"id\":\"pd6d8f50\",\"text\":\"Cushion\"},{\"id\":\"p0e99b9d\",\"text\":\"Book\"},{\"id\":\"p0a4bf58\",\"text\":\"Flower\"}]}','{\"choice\":\"p2c25976\"}','Change the factory sign-in details on smart devices.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Remote support · 20','There is a security risk on the computer screen at home. Which object should you tap?','{\"scene\":\"home\",\"location\":\"Home\",\"objects\":[{\"id\":\"p1feac1b\",\"label\":\"Glass\",\"emoji\":\"🥛\",\"x\":19,\"y\":19},{\"id\":\"pb1ca966\",\"label\":\"Plant\",\"emoji\":\"🪴\",\"x\":47,\"y\":25},{\"id\":\"pb156a40\",\"label\":\"Remote access request from an unknown person\",\"emoji\":\"🖥️\",\"x\":73,\"y\":18},{\"id\":\"pe75cfed\",\"label\":\"Book\",\"emoji\":\"📗\",\"x\":31,\"y\":66},{\"id\":\"p4c4ce70\",\"label\":\"Window\",\"emoji\":\"🪟\",\"x\":63,\"y\":62}],\"options\":[{\"id\":\"pb156a40\",\"text\":\"Remote access request from an unknown person\"},{\"id\":\"pb1ca966\",\"text\":\"Plant\"},{\"id\":\"p1feac1b\",\"text\":\"Glass\"},{\"id\":\"pe75cfed\",\"text\":\"Book\"},{\"id\":\"p4c4ce70\",\"text\":\"Window\"}]}','{\"choice\":\"pb156a40\"}','Never let someone you don\'t know connect to your computer remotely.','50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Cheat program · Library','A child wants to play games on the library computer. Which thing on the desk is dangerous? Tap it.','{\"scene\":\"library\",\"location\":\"Library computer corner\",\"objects\":[{\"id\":\"s1\",\"label\":\"\'free_cheat_program.exe\' file in the Downloads folder\",\"emoji\":\"💾\",\"x\":19,\"y\":43},{\"id\":\"s2\",\"label\":\"Headphones on the desk\",\"emoji\":\"🎧\",\"x\":80,\"y\":76},{\"id\":\"s3\",\"label\":\"Child-friendly encyclopedia website on the computer\",\"emoji\":\"🖥️\",\"x\":58,\"y\":30},{\"id\":\"s4\",\"label\":\"Library card scanner\",\"emoji\":\"🪪\",\"x\":82,\"y\":21},{\"id\":\"s5\",\"label\":\"Library\'s book borrowing scanner\",\"emoji\":\"📚\",\"x\":40,\"y\":77}],\"options\":[{\"id\":\"s1\",\"text\":\"\'free_cheat_program.exe\' file in the Downloads folder\"},{\"id\":\"s2\",\"text\":\"Headphones on the desk\"},{\"id\":\"s3\",\"text\":\"Child-friendly encyclopedia website on the computer\"},{\"id\":\"s4\",\"text\":\"Library card scanner\"},{\"id\":\"s5\",\"text\":\"Library\'s book borrowing scanner\"}]}','{\"choice\":\"s1\"}','A \'free cheat program\' downloaded from an unknown website often carries harmful software and can steal your game account. Never open files that promise cheats or free items; tell a trusted adult.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Free diamonds message · Game','While you play, the chat box fills up. Which thing on the screen puts your account in danger? Tap it.','{\"scene\":\"phone\",\"location\":\"Tablet screen, game chat\",\"objects\":[{\"id\":\"s1\",\"label\":\"\'Friends only\' option in the chat settings\",\"emoji\":\"⚙️\",\"x\":58,\"y\":27},{\"id\":\"s2\",\"label\":\"Your character\'s costume wardrobe\",\"emoji\":\"👕\",\"x\":71,\"y\":47},{\"id\":\"s3\",\"label\":\"Sound button in the corner of the screen\",\"emoji\":\"🔊\",\"x\":8,\"y\":62},{\"id\":\"s4\",\"label\":\"Chat message saying \'type your password, win 1000 free diamonds\'\",\"emoji\":\"💬\",\"x\":37,\"y\":37},{\"id\":\"s5\",\"label\":\"\'Daily quest complete\' text in the game\'s own menu\",\"emoji\":\"🏆\",\"x\":42,\"y\":80}],\"options\":[{\"id\":\"s1\",\"text\":\"\'Friends only\' option in the chat settings\"},{\"id\":\"s2\",\"text\":\"Your character\'s costume wardrobe\"},{\"id\":\"s3\",\"text\":\"Sound button in the corner of the screen\"},{\"id\":\"s4\",\"text\":\"Chat message saying \'type your password, win 1000 free diamonds\'\"},{\"id\":\"s5\",\"text\":\"\'Daily quest complete\' text in the game\'s own menu\"}]}','{\"choice\":\"s4\"}','No game asks for your password to give you free items; these messages are written to steal accounts. Never share your password, show the message to a trusted adult and use the \'Report\' button in the game.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Address envelope on stream · Home','You are about to start a game stream from your room. Which thing the camera can see gives away your personal information? Tap it.','{\"scene\":\"home\",\"location\":\"Kid\'s bedroom, streaming corner\",\"objects\":[{\"id\":\"s1\",\"label\":\"Desk lamp lighting the room\",\"emoji\":\"💡\",\"x\":70,\"y\":21},{\"id\":\"s2\",\"label\":\"Envelope with your home address and your school card on the wall, visible on camera\",\"emoji\":\"✉️\",\"x\":31,\"y\":58},{\"id\":\"s3\",\"label\":\"\'Only followers can chat\' setting in the streaming app\",\"emoji\":\"🛡️\",\"x\":29,\"y\":19},{\"id\":\"s4\",\"label\":\"Game controller on the desk\",\"emoji\":\"🎮\",\"x\":11,\"y\":75},{\"id\":\"s5\",\"label\":\"Microphone set up for the stream\",\"emoji\":\"🎙️\",\"x\":8,\"y\":43}],\"options\":[{\"id\":\"s1\",\"text\":\"Desk lamp lighting the room\"},{\"id\":\"s2\",\"text\":\"Envelope with your home address and your school card on the wall, visible on camera\"},{\"id\":\"s3\",\"text\":\"\'Only followers can chat\' setting in the streaming app\"},{\"id\":\"s4\",\"text\":\"Game controller on the desk\"},{\"id\":\"s5\",\"text\":\"Microphone set up for the stream\"}]}','{\"choice\":\"s2\"}','The envelope with your address and your school card in the background let strangers watching learn where you live and go to school. Before streaming, check what the camera can see and put personal things away.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Photo without permission · Classroom','At break time, everyone in class is busy with their phones. Which thing breaks a classmate\'s privacy? Tap it.','{\"scene\":\"class\",\"location\":\"Classroom, break time\",\"objects\":[{\"id\":\"s1\",\"label\":\"Class bookshelf\",\"emoji\":\"📚\",\"x\":32,\"y\":74},{\"id\":\"s2\",\"label\":\"Switched-off tablet on the teacher\'s desk\",\"emoji\":\"📱\",\"x\":72,\"y\":29},{\"id\":\"s3\",\"label\":\"Calculator charging\",\"emoji\":\"🧮\",\"x\":65,\"y\":54},{\"id\":\"s4\",\"label\":\"Lesson slides open on the smart board\",\"emoji\":\"🖥️\",\"x\":51,\"y\":14},{\"id\":\"s5\",\"label\":\"Photo of a classmate taken without asking, about to be sent to the class group\",\"emoji\":\"📸\",\"x\":17,\"y\":35}],\"options\":[{\"id\":\"s1\",\"text\":\"Class bookshelf\"},{\"id\":\"s2\",\"text\":\"Switched-off tablet on the teacher\'s desk\"},{\"id\":\"s3\",\"text\":\"Calculator charging\"},{\"id\":\"s4\",\"text\":\"Lesson slides open on the smart board\"},{\"id\":\"s5\",\"text\":\"Photo of a classmate taken without asking, about to be sent to the class group\"}]}','{\"choice\":\"s5\"}','Posting a classmate\'s photo to a group without asking breaks their privacy, and you cannot take it back. Before sharing, ask everyone in the photo; if anyone says no, don\'t share it.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Public profile · Social','You are editing your social media profile. Which item on the screen gives scammers easy information? Tap it.','{\"scene\":\"phone\",\"location\":\"Social media profile settings\",\"objects\":[{\"id\":\"s1\",\"label\":\"Two-step verification turned on\",\"emoji\":\"🔑\",\"x\":48,\"y\":79},{\"id\":\"s2\",\"label\":\"Account privacy: \'approved followers only\'\",\"emoji\":\"🔒\",\"x\":79,\"y\":72},{\"id\":\"s3\",\"label\":\"Public birthday, school name and neighbourhood in your bio\",\"emoji\":\"🎂\",\"x\":76,\"y\":20},{\"id\":\"s4\",\"label\":\"Muted notifications\",\"emoji\":\"🔕\",\"x\":40,\"y\":29},{\"id\":\"s5\",\"label\":\"Landscape picture as your profile photo\",\"emoji\":\"🏞️\",\"x\":27,\"y\":53}],\"options\":[{\"id\":\"s1\",\"text\":\"Two-step verification turned on\"},{\"id\":\"s2\",\"text\":\"Account privacy: \'approved followers only\'\"},{\"id\":\"s3\",\"text\":\"Public birthday, school name and neighbourhood in your bio\"},{\"id\":\"s4\",\"text\":\"Muted notifications\"},{\"id\":\"s5\",\"text\":\"Landscape picture as your profile photo\"}]}','{\"choice\":\"s3\"}','A public birthday, school name and neighbourhood can be used to guess security questions and write convincing messages aimed at you. Hide these details or show them only to close friends.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Paid scholarship ad · Cafe','You are looking at scholarship applications in a cafe. Which item on the table shows a sign of a scam? Tap it.','{\"scene\":\"cafe\",\"location\":\"Cafe, study table\",\"objects\":[{\"id\":\"s1\",\"label\":\"Laptop tab showing the school\'s official announcements page\",\"emoji\":\"💻\",\"x\":38,\"y\":56},{\"id\":\"s2\",\"label\":\"Application deadline notes in your notebook\",\"emoji\":\"📒\",\"x\":67,\"y\":44},{\"id\":\"s3\",\"label\":\"Social media ad on your phone saying \'scholarship guaranteed, pay a $25 application fee\'\",\"emoji\":\"📢\",\"x\":13,\"y\":42},{\"id\":\"s4\",\"label\":\"The cafe\'s menu board\",\"emoji\":\"📋\",\"x\":27,\"y\":80},{\"id\":\"s5\",\"label\":\"Headphones on the table\",\"emoji\":\"🎧\",\"x\":58,\"y\":78}],\"options\":[{\"id\":\"s1\",\"text\":\"Laptop tab showing the school\'s official announcements page\"},{\"id\":\"s2\",\"text\":\"Application deadline notes in your notebook\"},{\"id\":\"s3\",\"text\":\"Social media ad on your phone saying \'scholarship guaranteed, pay a $25 application fee\'\"},{\"id\":\"s4\",\"text\":\"The cafe\'s menu board\"},{\"id\":\"s5\",\"text\":\"Headphones on the table\"}]}','{\"choice\":\"s3\"}','Real scholarships do not charge a \'processing fee\' to apply; a scholarship promised for a fee is a classic scam. Check scholarship news only on your school\'s or the organisation\'s official page.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Shoulder surfing · Cafe','You are working in a busy cafe. Which item on your table shows private information to people around you? Tap it.','{\"scene\":\"cafe\",\"location\":\"Cafe, window table\",\"objects\":[{\"id\":\"s1\",\"label\":\"Tablet with a privacy screen filter\",\"emoji\":\"📱\",\"x\":23,\"y\":44},{\"id\":\"s2\",\"label\":\"Laptop facing the next table, showing an open salary spreadsheet\",\"emoji\":\"💻\",\"x\":66,\"y\":26},{\"id\":\"s3\",\"label\":\"Coffee cup on the table\",\"emoji\":\"☕\",\"x\":58,\"y\":50},{\"id\":\"s4\",\"label\":\"Personal hotspot you turned on from your phone\",\"emoji\":\"📶\",\"x\":11,\"y\":75},{\"id\":\"s5\",\"label\":\"Locked phone lying face down\",\"emoji\":\"🔒\",\"x\":65,\"y\":72}],\"options\":[{\"id\":\"s1\",\"text\":\"Tablet with a privacy screen filter\"},{\"id\":\"s2\",\"text\":\"Laptop facing the next table, showing an open salary spreadsheet\"},{\"id\":\"s3\",\"text\":\"Coffee cup on the table\"},{\"id\":\"s4\",\"text\":\"Personal hotspot you turned on from your phone\"},{\"id\":\"s5\",\"text\":\"Locked phone lying face down\"}]}','{\"choice\":\"s2\"}','A laptop facing the next table with a salary spreadsheet open lets anyone looking over your shoulder see or photograph it. Avoid opening sensitive files in public; if you must, use a privacy screen filter and face the screen toward a wall.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Fake front desk call · Hotel','You have just checked into your hotel room. Which item could be trying to steal your card details? Tap it.','{\"scene\":\"hotel\",\"location\":\"Hotel room\",\"objects\":[{\"id\":\"s1\",\"label\":\"Wi-Fi info card handed to you at the front desk\",\"emoji\":\"📶\",\"x\":10,\"y\":18},{\"id\":\"s2\",\"label\":\"Voicemail on the room phone from \'the front desk\' asking for your card number again\",\"emoji\":\"☎️\",\"x\":23,\"y\":51},{\"id\":\"s3\",\"label\":\"Closed and locked room safe\",\"emoji\":\"🧰\",\"x\":83,\"y\":28},{\"id\":\"s4\",\"label\":\"Security chain on the door\",\"emoji\":\"⛓️\",\"x\":62,\"y\":64},{\"id\":\"s5\",\"label\":\"Your own travel charging adapter\",\"emoji\":\"🔌\",\"x\":56,\"y\":27}],\"options\":[{\"id\":\"s1\",\"text\":\"Wi-Fi info card handed to you at the front desk\"},{\"id\":\"s2\",\"text\":\"Voicemail on the room phone from \'the front desk\' asking for your card number again\"},{\"id\":\"s3\",\"text\":\"Closed and locked room safe\"},{\"id\":\"s4\",\"text\":\"Security chain on the door\"},{\"id\":\"s5\",\"text\":\"Your own travel charging adapter\"}]}','{\"choice\":\"s2\"}','Hotels do not ask for card details by calling your room; a caller claiming to be the front desk may be a scammer. Hang up and check by going to the front desk in person or calling the number shown in the lobby.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Old access rights · 18','There is a security risk on the office access panel. Which object should you tap?','{\"scene\":\"office\",\"location\":\"Office\",\"objects\":[{\"id\":\"p64a1f19\",\"label\":\"File\",\"emoji\":\"📁\",\"x\":19,\"y\":19},{\"id\":\"p2a7a101\",\"label\":\"Cup\",\"emoji\":\"🥤\",\"x\":47,\"y\":25},{\"id\":\"pe582d2f\",\"label\":\"Pen\",\"emoji\":\"🖊️\",\"x\":73,\"y\":18},{\"id\":\"p008183e\",\"label\":\"Clock\",\"emoji\":\"⏰\",\"x\":31,\"y\":66},{\"id\":\"p1a26479\",\"label\":\"Still-active account of an employee who has left\",\"emoji\":\"👤\",\"x\":63,\"y\":62}],\"options\":[{\"id\":\"p1a26479\",\"text\":\"Still-active account of an employee who has left\"},{\"id\":\"p008183e\",\"text\":\"Clock\"},{\"id\":\"pe582d2f\",\"text\":\"Pen\"},{\"id\":\"p64a1f19\",\"text\":\"File\"},{\"id\":\"p2a7a101\",\"text\":\"Cup\"}]}','{\"choice\":\"p1a26479\"}','Accounts and access that are no longer needed should be closed.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','First bank card · Photos','You just got your first bank card and are tidying up your phone. Which item on the screen puts your card details at risk? Tap it.','{\"scene\":\"phone\",\"location\":\"Phone photo gallery and banking app\",\"objects\":[{\"id\":\"s1\",\"label\":\"Virtual card screen created in the banking app\",\"emoji\":\"💳\",\"x\":18,\"y\":42},{\"id\":\"s2\",\"label\":\"Alert for every purchase (turned on)\",\"emoji\":\"🔔\",\"x\":42,\"y\":13},{\"id\":\"s3\",\"label\":\"The phone\'s 6-digit screen lock\",\"emoji\":\"🔒\",\"x\":61,\"y\":59},{\"id\":\"s4\",\"label\":\"Low online shopping limit set in the banking app\",\"emoji\":\"🏦\",\"x\":42,\"y\":76},{\"id\":\"s5\",\"label\":\"Front and back photos of your bank card uploaded to the shared family album\",\"emoji\":\"🖼️\",\"x\":54,\"y\":32}],\"options\":[{\"id\":\"s1\",\"text\":\"Virtual card screen created in the banking app\"},{\"id\":\"s2\",\"text\":\"Alert for every purchase (turned on)\"},{\"id\":\"s3\",\"text\":\"The phone\'s 6-digit screen lock\"},{\"id\":\"s4\",\"text\":\"Low online shopping limit set in the banking app\"},{\"id\":\"s5\",\"text\":\"Front and back photos of your bank card uploaded to the shared family album\"}]}','{\"choice\":\"s5\"}','The front and back of a card show the card number, expiry date and security code; anyone in the shared album could use them to shop online. Delete the photo and, if needed, get a new card and use a virtual card.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Intern\'s customer list · Office','You are in the first week of a summer internship. Which item on your desk risks leaking company data? Tap it.','{\"scene\":\"office\",\"location\":\"Summer internship, office desk\",\"objects\":[{\"id\":\"s1\",\"label\":\"Company customer list open and about to be forwarded to your personal email\",\"emoji\":\"📧\",\"x\":81,\"y\":64},{\"id\":\"s2\",\"label\":\"Second monitor with a locked screen\",\"emoji\":\"🖥️\",\"x\":17,\"y\":12},{\"id\":\"s3\",\"label\":\"Intern access card around your neck\",\"emoji\":\"🪪\",\"x\":14,\"y\":40},{\"id\":\"s4\",\"label\":\"The company\'s secure connection (VPN) app, connected\",\"emoji\":\"🛡️\",\"x\":56,\"y\":80},{\"id\":\"s5\",\"label\":\"Printed meeting calendar on the desk (times only)\",\"emoji\":\"📅\",\"x\":36,\"y\":67}],\"options\":[{\"id\":\"s1\",\"text\":\"Company customer list open and about to be forwarded to your personal email\"},{\"id\":\"s2\",\"text\":\"Second monitor with a locked screen\"},{\"id\":\"s3\",\"text\":\"Intern access card around your neck\"},{\"id\":\"s4\",\"text\":\"The company\'s secure connection (VPN) app, connected\"},{\"id\":\"s5\",\"text\":\"Printed meeting calendar on the desk (times only)\"}]}','{\"choice\":\"s1\"}','Sending the company\'s customer list to your personal email takes the data outside the company\'s protection; this is a serious data leak and can break data protection laws. If you need to work from home, use the approved tools the company gives you.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Tournament sign-in window · Game','You are about to sign up for an online game tournament. Which item on the screen could be set up to steal your account? Tap it.','{\"scene\":\"home\",\"location\":\"Home, gaming computer\",\"objects\":[{\"id\":\"s1\",\"label\":\"Muted streaming microphone\",\"emoji\":\"🎙️\",\"x\":46,\"y\":27},{\"id\":\"s2\",\"label\":\"Game controller on the desk\",\"emoji\":\"🎮\",\"x\":58,\"y\":69},{\"id\":\"s3\",\"label\":\"6-digit code in the authenticator app\",\"emoji\":\"🔢\",\"x\":74,\"y\":40},{\"id\":\"s4\",\"label\":\"\'Sign in with your game account\' window on the tournament site that cannot be dragged outside the page\",\"emoji\":\"🪟\",\"x\":9,\"y\":22},{\"id\":\"s5\",\"label\":\"List of signed-in devices in the game platform\'s settings\",\"emoji\":\"📋\",\"x\":80,\"y\":63}],\"options\":[{\"id\":\"s1\",\"text\":\"Muted streaming microphone\"},{\"id\":\"s2\",\"text\":\"Game controller on the desk\"},{\"id\":\"s3\",\"text\":\"6-digit code in the authenticator app\"},{\"id\":\"s4\",\"text\":\"\'Sign in with your game account\' window on the tournament site that cannot be dragged outside the page\"},{\"id\":\"s5\",\"text\":\"List of signed-in devices in the game platform\'s settings\"}]}','{\"choice\":\"s4\"}','A fake \'sign-in window\' drawn inside the page looks like a real browser window, but its address bar is fake; the password you type goes straight to the attacker. Always sign in through the platform\'s own app or by typing its address yourself.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Open remote desktop · Office','At lunchtime the open-plan office is empty. Which item on the desks opens the door to unauthorised access? Tap it.','{\"scene\":\"office\",\"location\":\"Office, open-plan area\",\"objects\":[{\"id\":\"s1\",\"label\":\"Workstation with a locked screen\",\"emoji\":\"🔒\",\"x\":86,\"y\":55},{\"id\":\"s2\",\"label\":\"Conference camera with its cover closed\",\"emoji\":\"📷\",\"x\":32,\"y\":51},{\"id\":\"s3\",\"label\":\"Secure printer that releases prints only with a staff card\",\"emoji\":\"🖨️\",\"x\":66,\"y\":30},{\"id\":\"s4\",\"label\":\"Remote desktop session connected to a server, left open on screen while its owner is away\",\"emoji\":\"🖥️\",\"x\":35,\"y\":75},{\"id\":\"s5\",\"label\":\"Encrypted company laptop with an inventory tag (in a drawer)\",\"emoji\":\"💼\",\"x\":54,\"y\":55}],\"options\":[{\"id\":\"s1\",\"text\":\"Workstation with a locked screen\"},{\"id\":\"s2\",\"text\":\"Conference camera with its cover closed\"},{\"id\":\"s3\",\"text\":\"Secure printer that releases prints only with a staff card\"},{\"id\":\"s4\",\"text\":\"Remote desktop session connected to a server, left open on screen while its owner is away\"},{\"id\":\"s5\",\"text\":\"Encrypted company laptop with an inventory tag (in a drawer)\"}]}','{\"choice\":\"s4\"}','A remote desktop session left open gives access to the server with your permissions; anyone who sits down can use them. When you leave your desk, sign out or lock the screen and end the remote connection.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Whiteboard in the background · Home','You are about to join a video call with a client from home. Which item in the camera view leaks confidential information? Tap it.','{\"scene\":\"home\",\"location\":\"Home office, video call\",\"objects\":[{\"id\":\"s1\",\"label\":\"Whiteboard behind you, visible on camera, with client names and contract amounts\",\"emoji\":\"📝\",\"x\":12,\"y\":54},{\"id\":\"s2\",\"label\":\"Muted microphone in the meeting app\",\"emoji\":\"🎙️\",\"x\":42,\"y\":78},{\"id\":\"s3\",\"label\":\"Personal phone with a locked screen\",\"emoji\":\"📱\",\"x\":58,\"y\":26},{\"id\":\"s4\",\"label\":\"Wired headphones\",\"emoji\":\"🎧\",\"x\":83,\"y\":63},{\"id\":\"s5\",\"label\":\"Up-to-date laptop provided by the company\",\"emoji\":\"💻\",\"x\":34,\"y\":14}],\"options\":[{\"id\":\"s1\",\"text\":\"Whiteboard behind you, visible on camera, with client names and contract amounts\"},{\"id\":\"s2\",\"text\":\"Muted microphone in the meeting app\"},{\"id\":\"s3\",\"text\":\"Personal phone with a locked screen\"},{\"id\":\"s4\",\"text\":\"Wired headphones\"},{\"id\":\"s5\",\"text\":\"Up-to-date laptop provided by the company\"}]}','{\"choice\":\"s1\"}','Client names and contract amounts on a whiteboard seen on camera leak for good if the call is recorded or someone takes a screenshot. Check your camera view before the call; blurring the background alone may not hide everything.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Scans in the shared folder · Library','You scanned some documents at the library and went back to work. Which item here leaves your personal data exposed? Tap it.','{\"scene\":\"library\",\"location\":\"Library, scanning and printing area\",\"objects\":[{\"id\":\"s1\",\"label\":\"Library card reader\",\"emoji\":\"🪪\",\"x\":62,\"y\":27},{\"id\":\"s2\",\"label\":\"VPN connection turned on on your own laptop\",\"emoji\":\"🛡️\",\"x\":16,\"y\":33},{\"id\":\"s3\",\"label\":\"The library\'s book borrowing kiosk\",\"emoji\":\"📚\",\"x\":85,\"y\":75},{\"id\":\"s4\",\"label\":\"Locked locker with the key in your pocket\",\"emoji\":\"🔐\",\"x\":44,\"y\":61},{\"id\":\"s5\",\"label\":\"Your ID and rental contract scans left in the shared scanner\'s folder\",\"emoji\":\"🗂️\",\"x\":42,\"y\":37}],\"options\":[{\"id\":\"s1\",\"text\":\"Library card reader\"},{\"id\":\"s2\",\"text\":\"VPN connection turned on on your own laptop\"},{\"id\":\"s3\",\"text\":\"The library\'s book borrowing kiosk\"},{\"id\":\"s4\",\"text\":\"Locked locker with the key in your pocket\"},{\"id\":\"s5\",\"text\":\"Your ID and rental contract scans left in the shared scanner\'s folder\"}]}','{\"choice\":\"s5\"}','ID and contract scans left in the shared scanner\'s folder can be copied by anyone who comes after you and used for identity fraud. Once you have saved the scan to your own USB stick or account, delete it from the shared folder.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Grandchild\'s new number · Messages','You have a few new messages on your phone. Which one could have been sent to scam you? Tap it.','{\"scene\":\"phone\",\"location\":\"Phone messages screen\",\"objects\":[{\"id\":\"s1\",\"label\":\"Missed call from your son\'s saved number\",\"emoji\":\"📞\",\"x\":14,\"y\":56},{\"id\":\"s2\",\"label\":\"System update notice in the Settings menu\",\"emoji\":\"⚙️\",\"x\":42,\"y\":22},{\"id\":\"s3\",\"label\":\"Photo your grandchild shared in the family group\",\"emoji\":\"🖼️\",\"x\":80,\"y\":44},{\"id\":\"s4\",\"label\":\"Message from an unsaved number: \'Grandma, my phone broke, I need money urgently\'\",\"emoji\":\"💬\",\"x\":39,\"y\":52},{\"id\":\"s5\",\"label\":\"\'Pension paid\' notice from your bank\'s own app\",\"emoji\":\"🏦\",\"x\":9,\"y\":21}],\"options\":[{\"id\":\"s1\",\"text\":\"Missed call from your son\'s saved number\"},{\"id\":\"s2\",\"text\":\"System update notice in the Settings menu\"},{\"id\":\"s3\",\"text\":\"Photo your grandchild shared in the family group\"},{\"id\":\"s4\",\"text\":\"Message from an unsaved number: \'Grandma, my phone broke, I need money urgently\'\"},{\"id\":\"s5\",\"text\":\"\'Pension paid\' notice from your bank\'s own app\"}]}','{\"choice\":\"s4\"}','Someone writing \'my phone broke, I need money urgently\' from an unsaved number may be pretending to be your grandchild. Before sending money, call your grandchild on their old saved number or ask another family member.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Customs fee text · Parcel','You are checking your phone and tablet in the living room. Which item could have been sent to steal your money and card details? Tap it.','{\"scene\":\"home\",\"location\":\"Home, living room\",\"objects\":[{\"id\":\"s1\",\"label\":\"Official pension app from the government agency, downloaded from the app store, on the tablet\",\"emoji\":\"📱\",\"x\":25,\"y\":47},{\"id\":\"s2\",\"label\":\"Text with a link on your phone: \'Your parcel is waiting, pay a $2.90 customs fee\'\",\"emoji\":\"📦\",\"x\":75,\"y\":59},{\"id\":\"s3\",\"label\":\"Family address book next to the landline\",\"emoji\":\"📒\",\"x\":66,\"y\":24},{\"id\":\"s4\",\"label\":\"Doorbell camera with its password changed\",\"emoji\":\"🔔\",\"x\":20,\"y\":77},{\"id\":\"s5\",\"label\":\"TV remote\",\"emoji\":\"📺\",\"x\":15,\"y\":10}],\"options\":[{\"id\":\"s1\",\"text\":\"Official pension app from the government agency, downloaded from the app store, on the tablet\"},{\"id\":\"s2\",\"text\":\"Text with a link on your phone: \'Your parcel is waiting, pay a $2.90 customs fee\'\"},{\"id\":\"s3\",\"text\":\"Family address book next to the landline\"},{\"id\":\"s4\",\"text\":\"Doorbell camera with its password changed\"},{\"id\":\"s5\",\"text\":\"TV remote\"}]}','{\"choice\":\"s2\"}','A parcel text with a link asking for a small \'customs fee\' leads to a fake page that collects card details. Do not tap the link; track your parcel only in the delivery company\'s official app or on a number you look up yourself.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Admin panel on guest Wi-Fi · Meeting','The client meeting is over and the guests are having coffee in the room. Which item creates a serious security hole? Tap it.','{\"scene\":\"office\",\"location\":\"Office meeting room\",\"objects\":[{\"id\":\"s1\",\"label\":\"Guest Wi-Fi info card on the table\",\"emoji\":\"📶\",\"x\":14,\"y\":69},{\"id\":\"s2\",\"label\":\"Muted conference speaker\",\"emoji\":\"🔈\",\"x\":41,\"y\":47},{\"id\":\"s3\",\"label\":\"Admin panel left signed in on a smart screen connected to guest Wi-Fi\",\"emoji\":\"📺\",\"x\":31,\"y\":16},{\"id\":\"s4\",\"label\":\"Wireless presentation adapter with a company inventory tag\",\"emoji\":\"📡\",\"x\":79,\"y\":10},{\"id\":\"s5\",\"label\":\"Room booking tablet by the door\",\"emoji\":\"📅\",\"x\":73,\"y\":65}],\"options\":[{\"id\":\"s1\",\"text\":\"Guest Wi-Fi info card on the table\"},{\"id\":\"s2\",\"text\":\"Muted conference speaker\"},{\"id\":\"s3\",\"text\":\"Admin panel left signed in on a smart screen connected to guest Wi-Fi\"},{\"id\":\"s4\",\"text\":\"Wireless presentation adapter with a company inventory tag\"},{\"id\":\"s5\",\"text\":\"Room booking tablet by the door\"}]}','{\"choice\":\"s3\"}','An admin panel left signed in on a smart screen connected to guest Wi-Fi lets anyone in the room change the device\'s settings and networks. Sign out of admin sessions and keep meeting-room devices on a network separate from guests.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Approval request after request · Two-step','Notifications hit your phone at midnight. Which item on the screen shows someone trying to break into your account? Tap it.','{\"scene\":\"phone\",\"location\":\"Phone lock screen\",\"objects\":[{\"id\":\"s1\",\"label\":\"Locked password manager app\",\"emoji\":\"🔐\",\"x\":64,\"y\":12},{\"id\":\"s2\",\"label\":\"Calendar reminder for a morning meeting\",\"emoji\":\"📅\",\"x\":9,\"y\":19},{\"id\":\"s3\",\"label\":\"Passkey sign-in request you started on your own laptop\",\"emoji\":\"🔑\",\"x\":71,\"y\":42},{\"id\":\"s4\",\"label\":\"Sign-in you started on your own computer, asking you to match the number on screen\",\"emoji\":\"🔢\",\"x\":41,\"y\":20},{\"id\":\"s5\",\"label\":\"7th \'Is this you signing in? Approve\' notification, arriving at 2:14 AM\",\"emoji\":\"📲\",\"x\":34,\"y\":65}],\"options\":[{\"id\":\"s1\",\"text\":\"Locked password manager app\"},{\"id\":\"s2\",\"text\":\"Calendar reminder for a morning meeting\"},{\"id\":\"s3\",\"text\":\"Passkey sign-in request you started on your own laptop\"},{\"id\":\"s4\",\"text\":\"Sign-in you started on your own computer, asking you to match the number on screen\"},{\"id\":\"s5\",\"text\":\"7th \'Is this you signing in? Approve\' notification, arriving at 2:14 AM\"}]}','{\"choice\":\"s5\"}','A stream of sign-in approval requests you did not start means the attacker knows your password and hopes you tap \'Approve\' out of tiredness. Never approve: deny it, change your password and tell your IT team.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','Add-on asking too much · App access','A colleague suggested a tool for merging PDFs. Which item on the screen puts your account at risk? Tap it.','{\"scene\":\"office\",\"location\":\"Office, finance team desk\",\"objects\":[{\"id\":\"s1\",\"label\":\"Folder set to \'team only\' in the company file share\",\"emoji\":\"🗂️\",\"x\":72,\"y\":36},{\"id\":\"s2\",\"label\":\"Security key sign-in turned on for your work account\",\"emoji\":\"🔑\",\"x\":40,\"y\":41},{\"id\":\"s3\",\"label\":\"Approval window asking to let \'PDF Merger\' read, send and delete all your emails\",\"emoji\":\"🧩\",\"x\":53,\"y\":63},{\"id\":\"s4\",\"label\":\"Autofill icon of the company password manager\",\"emoji\":\"🔐\",\"x\":10,\"y\":60},{\"id\":\"s5\",\"label\":\"Second monitor with a locked screen\",\"emoji\":\"🖥️\",\"x\":44,\"y\":10}],\"options\":[{\"id\":\"s1\",\"text\":\"Folder set to \'team only\' in the company file share\"},{\"id\":\"s2\",\"text\":\"Security key sign-in turned on for your work account\"},{\"id\":\"s3\",\"text\":\"Approval window asking to let \'PDF Merger\' read, send and delete all your emails\"},{\"id\":\"s4\",\"text\":\"Autofill icon of the company password manager\"},{\"id\":\"s5\",\"text\":\"Second monitor with a locked screen\"}]}','{\"choice\":\"s3\"}','A simple PDF tool asking to read, send and delete all your emails is a trap. If you approve, the app gets lasting access to your account without your password or two-step verification. Deny it, use IT-approved tools and report the app.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (3,'hunt','QR flyer under the door · Hotel','Back at your hotel room, you find some things by the door. Which item could have been left to steal your payment details? Tap it.','{\"scene\":\"hotel\",\"location\":\"Hotel room, entrance\",\"objects\":[{\"id\":\"s1\",\"label\":\"Flyer slipped under the door: \'Scan the QR code to order room service, pay by card\'\",\"emoji\":\"🔳\",\"x\":19,\"y\":20},{\"id\":\"s2\",\"label\":\"Your own travel charging adapter\",\"emoji\":\"🔌\",\"x\":79,\"y\":52},{\"id\":\"s3\",\"label\":\"Room key card handed to you at the front desk\",\"emoji\":\"🗝️\",\"x\":26,\"y\":43},{\"id\":\"s4\",\"label\":\"Hotel-branded Wi-Fi info card in the room\",\"emoji\":\"📶\",\"x\":60,\"y\":78},{\"id\":\"s5\",\"label\":\"Hotel welcome screen on the TV\",\"emoji\":\"📺\",\"x\":52,\"y\":31}],\"options\":[{\"id\":\"s1\",\"text\":\"Flyer slipped under the door: \'Scan the QR code to order room service, pay by card\'\"},{\"id\":\"s2\",\"text\":\"Your own travel charging adapter\"},{\"id\":\"s3\",\"text\":\"Room key card handed to you at the front desk\"},{\"id\":\"s4\",\"text\":\"Hotel-branded Wi-Fi info card in the room\"},{\"id\":\"s5\",\"text\":\"Hotel welcome screen on the TV\"}]}','{\"choice\":\"s1\"}','A flyer slipped under the door saying \'scan the QR code for room service\' is a QR scam; the code leads to a fake payment page that collects card details. Order and pay by asking the front desk or using the hotel\'s official in-room menu.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 3','Which extra security step fits best?','{\"stage\":\"kalkan\",\"icon\":\"🔑\",\"options\":[{\"id\":\"a\",\"text\":\"Two-step verification\"},{\"id\":\"b\",\"text\":\"Sticking the password on a note\"},{\"id\":\"c\",\"text\":\"Sharing it publicly\"}]}','{\"choice\":\"a\"}','Two-step verification protects your account with an extra layer, even if someone learns your password.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 6','You get a suspicious sign-in alert. What should you do?','{\"stage\":\"kalkan\",\"icon\":\"🛡️\",\"options\":[{\"id\":\"a\",\"text\":\"Check the account another way, on your own\"},{\"id\":\"b\",\"text\":\"Click every link in the email\"},{\"id\":\"c\",\"text\":\"Share the verification code\"}]}','{\"choice\":\"a\"}','Do not use the link in the suspicious message. Check your account yourself in the official app.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 9','You hear news about a data breach. What do you do?','{\"stage\":\"kalkan\",\"icon\":\"🔐\",\"options\":[{\"id\":\"a\",\"text\":\"Change that password, and change it anywhere else you reused it\"},{\"id\":\"b\",\"text\":\"Do nothing\"},{\"id\":\"c\",\"text\":\"Send your password to everyone\"}]}','{\"choice\":\"a\"}','Change the leaked password, and change it anywhere else you used the same one.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 12','Which choice protects an account best?','{\"stage\":\"kalkan\",\"icon\":\"⚡\",\"options\":[{\"id\":\"a\",\"text\":\"A short password\"},{\"id\":\"b\",\"text\":\"A long unique password plus two-step verification\"},{\"id\":\"c\",\"text\":\"Only a username\"}]}','{\"choice\":\"b\"}','A unique password together with two-step verification works much better than either one alone.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 15','A site asks you to change your password every 30 days. What is the safe habit?','{\"stage\":\"kalkan\",\"icon\":\"🔑\",\"options\":[{\"id\":\"a\",\"text\":\"Adding a predictable number that counts up\"},{\"id\":\"b\",\"text\":\"Keeping a unique password; changing it at once after a breach\"},{\"id\":\"c\",\"text\":\"Emailing the password to yourself\"}]}','{\"choice\":\"b\"}','Frequent changes for no reason push people into predictable patterns. Change it right away if there is a breach or someone else got in.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Shield Mission 18','You notice you use the same password on two accounts. What is the best step?','{\"stage\":\"kalkan\",\"icon\":\"🛡️\",\"options\":[{\"id\":\"a\",\"text\":\"Leave it on both\"},{\"id\":\"b\",\"text\":\"Create a new, different password for each account\"},{\"id\":\"c\",\"text\":\"Add 1 to the end of one of them\"}]}','{\"choice\":\"b\"}','Reusing a password lets a breach at one service spread to your other accounts. Every account needs its own password.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Passkey choice · 14','If a service supports it, why is a passkey a good option?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"It can offer a sign-in built to resist phishing\"},{\"id\":\"s3\",\"text\":\"It types the same password everywhere\"},{\"id\":\"s2\",\"text\":\"It emails your login details\"}],\"interaction_hint\":\"Example passwords and account situations are made up; never type your real password.\"}','{\"choice\":\"s1\"}','When set up properly, passkeys give strong protection against fake login pages.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Password reset address · 16','You are waiting for a password reset link. What is the safest approach?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s3\",\"text\":\"Clicking without checking the address\"},{\"id\":\"s2\",\"text\":\"Starting the password reset from the app you know\"},{\"id\":\"s1\",\"text\":\"Replying with your login details\"}],\"interaction_hint\":\"Example passwords and account situations are made up; never type your real password.\"}','{\"choice\":\"s2\"}','Make sure the link really belongs to the service. Starting the reset yourself in the app you know is safest.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Admin account · 17','What is the best way to secure an account with high-level access?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s3\",\"text\":\"Sharing the password in the team chat\"},{\"id\":\"s2\",\"text\":\"All admins using the same password\"},{\"id\":\"s1\",\"text\":\"Using unique login details and strong two-step verification\"}],\"interaction_hint\":\"Example passwords and account situations are made up; never type your real password.\"}','{\"choice\":\"s1\"}','Accounts with special access need personal login details and strong two-step verification.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Family account · 20','Family members manage different accounts with one password. What is safer?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s2\",\"text\":\"Using separate unique passwords for the accounts\"},{\"id\":\"s3\",\"text\":\"Sharing the same password with everyone\"},{\"id\":\"s1\",\"text\":\"Writing the password on the TV screen\"}],\"interaction_hint\":\"Example passwords and account situations are made up; never type your real password.\"}','{\"choice\":\"s2\"}','Use a unique password for each account and give each person only the access they need.','50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Signed in at school · Session safety','You signed in to your game account in the school computer lab and the lesson is over. The computer asks \'Remember me?\'. What do you do?','{\"icon\":\"🖥️\",\"options\":[{\"id\":\"s1\",\"text\":\"I say no, sign out when I finish, and close the browser\"},{\"id\":\"s2\",\"text\":\"I say yes, so I don\'t have to type my password tomorrow\"},{\"id\":\"s3\",\"text\":\"I say yes but turn off the screen, so nobody sees\"},{\"id\":\"s4\",\"text\":\"I close the tab, that is enough\"}]}','{\"choice\":\"s1\"}','On a shared computer, \'Remember me\' lets the next person get into your account. Say no, sign out when you finish, and close the browser.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Free gems page · Game account','Under a video there is a link: \'Type your username and password, get 5000 free gems\'. What do you do?','{\"icon\":\"🎮\",\"options\":[{\"id\":\"s1\",\"text\":\"I type only my username, not my password\"},{\"id\":\"s2\",\"text\":\"My friend can try first; if the gems arrive, I\'ll do it too\"},{\"id\":\"s3\",\"text\":\"I don\'t open the link, don\'t type my password, and show a grown-up\"},{\"id\":\"s4\",\"text\":\"I type my old password, I don\'t use it anymore anyway\"}]}','{\"choice\":\"s3\"}','Games never ask for your password on another page to give you free items. These pages steal accounts; don\'t open the link and show it to a grown-up.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','A friend saw your password · Change password','While you signed in to your game account, your friend watched your keyboard, saw your password and said it out loud, laughing. What is the best thing to do?','{\"icon\":\"🔑\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s my friend, so it\'s fine. I carry on\"},{\"id\":\"s2\",\"text\":\"With a grown-up, I change my password to a new one right away\"},{\"id\":\"s3\",\"text\":\"I add a number to the end of my password, that is enough\"},{\"id\":\"s4\",\"text\":\"I ask my friend to forget my password\"}]}','{\"choice\":\"s2\"}','A password someone else knows is not secret anymore; even a friend could get into your account. With a grown-up, change it to a new, long password.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Teacher\'s first sign-in rule · School account','Your teacher says: \'The first time you sign in to your school account, create your own password and don\'t tell anyone.\' What do you think of this?','{\"icon\":\"🏫\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s suspicious; the teacher might want to know my password\"},{\"id\":\"s2\",\"text\":\"No need, I\'ll keep using the temporary password the teacher gave\"},{\"id\":\"s3\",\"text\":\"I create my password and write it on the class noticeboard so I don\'t forget\"},{\"id\":\"s4\",\"text\":\"It\'s a good request; I create my own password and share it with no one\"}]}','{\"choice\":\"s4\"}','This is a safe, correct request: swapping the temporary password for your own secret one protects your account. You don\'t need to tell anyone your password, not even your teacher.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Before changing phones · Authenticator app','You are moving to a new phone. The authenticator app on your old phone makes the codes for your social media sign-in. What do you do first?','{\"icon\":\"📱\",\"options\":[{\"id\":\"s1\",\"text\":\"I reset the old phone now; the codes will appear on the new phone by themselves\"},{\"id\":\"s2\",\"text\":\"I move the accounts to the new phone and save the recovery codes somewhere safe\"},{\"id\":\"s3\",\"text\":\"I turn off two-step verification completely and won\'t forget to turn it back on\"},{\"id\":\"s4\",\"text\":\"I screenshot the codes and send them to a friend\"}]}','{\"choice\":\"s2\"}','If you reset the old phone before moving the authenticator app or saving recovery codes, you may lock yourself out. Move the accounts to the new phone first and keep recovery codes somewhere safe.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Follower app · Third-party access','An app says: \'Enter your social media username and password, get 1000 followers a day.\' What is the right judgement?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"I don\'t give it; a password goes only into the service\'s own sign-in screen\"},{\"id\":\"s2\",\"text\":\"I give my password and change it when I\'m done\"},{\"id\":\"s3\",\"text\":\"It\'s in the app store, so it\'s safe\"},{\"id\":\"s4\",\"text\":\"If the reviews are good, giving my password is fine\"}]}','{\"choice\":\"s1\"}','Giving your password to another app hands a stranger the key to your account; these apps can take it over for spam or to sell it. Only type your password on the service\'s own sign-in page.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Paste allowed · Password manager','A new site lets you paste a password you copied from your password manager. How do you judge this?','{\"icon\":\"🔑\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s a security hole; the site should block pasting\"},{\"id\":\"s2\",\"text\":\"Good design; it makes long random passwords and password managers easier to use\"},{\"id\":\"s3\",\"text\":\"It\'s only safe for short passwords\"},{\"id\":\"s4\",\"text\":\"Writing the password in a file and reading it from there is safer than pasting\"}]}','{\"choice\":\"s2\"}','This is good design: NIST guidance says sites should allow pasting and password managers, because that encourages long random passwords. Sites that block it push people to short ones.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','In-app passkey offer · Passkey','You opened your bank\'s official app yourself, and it says \'Create a passkey on this device\'. What is the right judgement?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s definitely a scam; I should delete the app\"},{\"id\":\"s2\",\"text\":\"If I accept, I\'ll be sending my screen lock code to the bank\"},{\"id\":\"s3\",\"text\":\"It\'s genuine; it comes from the official app, so I can create it, and it resists phishing\"},{\"id\":\"s4\",\"text\":\"It only counts if I also confirm through a link sent by text message\"}]}','{\"choice\":\"s3\"}','If the request comes from inside the official app you opened, it is a real security upgrade. A passkey stays on your device, does not work on fake sites and resists phishing.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Game account password · Word string','Which password for your new game account is hardest to guess?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"kitty123\"},{\"id\":\"s2\",\"text\":\"Max2015\"},{\"id\":\"s3\",\"text\":\"Green-Cloud-Pizza-Plane\"},{\"id\":\"s4\",\"text\":\"12345678\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s3\"}','Four unrelated words are long and hard to guess. Names, birth years and runs like 123 are the first things attackers try.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Social media password · Team and name','Which password is strongest for your social media account?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"Liverpool1892\"},{\"id\":\"s2\",\"text\":\"Sarah2008!\"},{\"id\":\"s3\",\"text\":\"bird-book-hill-lemon-7\"},{\"id\":\"s4\",\"text\":\"qwerty123\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s3\"}','Team names, first names and years are the first patterns attackers try; adding an exclamation mark adds little. A long string of randomly chosen words is much stronger.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Someone leaves the team · 18','What should happen after a team member leaves?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s3\",\"text\":\"The shared password should stay the same\"},{\"id\":\"s2\",\"text\":\"Remove their access and replace shared secrets where needed\"},{\"id\":\"s1\",\"text\":\"Give the account to everyone\"}],\"interaction_hint\":\"Example passwords and account situations are made up; never type your real password.\"}','{\"choice\":\"s2\"}','The person\'s access should be removed, and any shared keys or passwords they knew should be replaced.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','First bank card PIN · Card PIN','You got your first bank card and need to pick a 4-digit PIN. Which is the best choice?','{\"icon\":\"💳\",\"options\":[{\"id\":\"s1\",\"text\":\"My birth year, I could never forget it\"},{\"id\":\"s2\",\"text\":\"4 random digits unrelated to my personal details, which I memorise\"},{\"id\":\"s3\",\"text\":\"A neat pattern with no repeats, like 1357\"},{\"id\":\"s4\",\"text\":\"Random digits, with a small note tucked inside the card holder\"}]}','{\"choice\":\"s2\"}','Birth years, repeated or ordered digits are tried first, and a written note helps whoever finds a lost card. Pick random digits unrelated to you and memorise them.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Password change you didn\'t make · Account takeover','An email says \'Your game account password was changed. If this wasn\'t you, click here.\' You really didn\'t change it. What is the best step?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"I click the link in the email and get my password back right away\"},{\"id\":\"s2\",\"text\":\"I delete the email; I didn\'t change anything, so it doesn\'t matter\"},{\"id\":\"s3\",\"text\":\"I reply to the email and ask support to send me my password\"},{\"id\":\"s4\",\"text\":\"I open the site myself, reset the password, sign out all sessions and check my recovery details\"}]}','{\"choice\":\"s4\"}','It could be real or fake; the link may be phishing. Open the app or site yourself, reset the password, sign out all sessions, check the recovery email and turn on two-step verification.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Scholarship portal says no · Leaked list','A scholarship application portal says: \'This password appears in known data leaks, choose another one.\' What does this mean?','{\"icon\":\"🎓\",\"options\":[{\"id\":\"s1\",\"text\":\"The portal stole my password; I should give up on applying\"},{\"id\":\"s2\",\"text\":\"I add an exclamation mark to the end and try again\"},{\"id\":\"s3\",\"text\":\"The portal is right; I choose a long, unique password just for this account\"},{\"id\":\"s4\",\"text\":\"The portal is wrong; I try the same password in another browser\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password.\"}','{\"choice\":\"s3\"}','This is safe behaviour: current guidance tells services to check new passwords against leaked lists. Choose a new, long password used only for this account.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Order you don\'t recognise · Credential stuffing','There is an order you don\'t recognise in your shopping account. You also used the same password on a forum that was leaked last month. What is the best plan?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"I change only the shopping site password; the forum doesn\'t matter\"},{\"id\":\"s2\",\"text\":\"I cancel the order and keep the password; it may be a coincidence\"},{\"id\":\"s3\",\"text\":\"I delete my forum account and the problem solves itself\"},{\"id\":\"s4\",\"text\":\"I replace it with a unique password on every account that used it, turn on two-step verification and report the order\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password.\"}','{\"choice\":\"s4\"}','This is credential stuffing: a leaked password is tried on other sites. Replace it with unique passwords everywhere you used it, turn on two-step verification, sign out sessions and report the order.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','One try per account · Password spraying','Company logs show sign-in attempts on hundreds of accounts on the same day, each tried once with the password \'Autumn2026!\'. What is the best measure?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"Block common and leaked passwords and require phishing-resistant two-step verification\"},{\"id\":\"s2\",\"text\":\"Lower the account lockout limit to a single attempt\"},{\"id\":\"s3\",\"text\":\"Force everyone to change their password every month\"},{\"id\":\"s4\",\"text\":\"Require at least one symbol and one capital letter\"}]}','{\"choice\":\"s1\"}','This is password spraying: a few common passwords are tried on each account to avoid lockouts. Blocking common and leaked passwords plus phishing-resistant two-step verification works best.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Sudden \'No service\' · SIM swap','Your phone suddenly shows \'No service\' for no reason, and soon after your email gets a \'sign-in from a new device\' alert. What do you do?','{\"icon\":\"📱\",\"options\":[{\"id\":\"s1\",\"text\":\"I restart the phone and wait a day\"},{\"id\":\"s2\",\"text\":\"I call my mobile provider from another phone now, change my passwords and switch from text codes to stronger verification\"},{\"id\":\"s3\",\"text\":\"I treat the email alert as spam and ignore it\"},{\"id\":\"s4\",\"text\":\"I complain using the \'This wasn\'t me\' link in the alert email\"}]}','{\"choice\":\"s2\"}','This may be a SIM swap: an attacker moves your number to their own SIM and receives your text codes. Call your mobile provider from another phone now, change key passwords, and switch from text codes to an app or passkey.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Code request from a grandchild · Account takeover','A message from an unknown number says: \'Grandma, this is my new number. A code was sent to you by mistake, can you tell me it?\' What do you do?','{\"icon\":\"📱\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s my grandchild, so I send the code right away\"},{\"id\":\"s2\",\"text\":\"I ask for their name first; if it\'s right, I give the code\"},{\"id\":\"s3\",\"text\":\"I don\'t share the code; I call my grandchild on the old number I know and ask\"},{\"id\":\"s4\",\"text\":\"I send half the code and say the rest on the phone\"}]}','{\"choice\":\"s3\"}','That code is for linking your messaging or bank account to a new device; sharing it lets someone take over the account. Tell nobody the code and call your grandchild on the old number you know.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Government portal reset call · Impersonation','Someone claiming to be a government official says: \'Your password for the official government portal was reset. Read me the code sent to your phone, or your pension will stop.\' What do you do?','{\"icon\":\"🏛️\",\"options\":[{\"id\":\"s1\",\"text\":\"I hang up, don\'t read the code, and call the agency\'s official number myself\"},{\"id\":\"s2\",\"text\":\"If they say my national ID number correctly, I read the code\"},{\"id\":\"s3\",\"text\":\"I read the code but don\'t tell them my password\"},{\"id\":\"s4\",\"text\":\"I call back the number the official gave me and tell them the code there\"}]}','{\"choice\":\"s1\"}','Real agencies never ask for a password or verification code by phone; the pension threat is there to rush you. Hang up, read the code to no one, and call the agency\'s official number yourself.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Complex-looking trap · Symbols for letters','Which password looks complex but can be guessed in seconds?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"leaf-train-soup-battery\"},{\"id\":\"s2\",\"text\":\"P@ssw0rd2024!\"},{\"id\":\"s3\",\"text\":\"zN4#qT8!vL2@pW\"},{\"id\":\"s4\",\"text\":\"ocean-pencil-stove-pear-3\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s2\"}','Swapping letters in the word \'Password\' for @ and 0 does not fool attackers; they try those swaps automatically. Length and randomness matter more than symbols.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Work account password · Company and month','You are setting the password for your email at your first job. Which is the best choice?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"Company2025!\"},{\"id\":\"s2\",\"text\":\"June.2025\"},{\"id\":\"s3\",\"text\":\"James1985\"},{\"id\":\"s4\",\"text\":\"orange-compass-jar-night\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s4\"}','Company name, month and year are the patterns employees choose most, and they are on attackers\' lists. A long password of random words kept in a password manager is safest.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Grandchild\'s birthday · Personal info','You are choosing a new password for your banking app. Which is safest?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"Ethan2012\"},{\"id\":\"s2\",\"text\":\"18061955\"},{\"id\":\"s3\",\"text\":\"tea-garden-umbrella-train\"},{\"id\":\"s4\",\"text\":\"123456Ab\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s3\"}','Birth dates, a grandchild\'s name and 123456 are easy to find on social media or are tried first. A password made of random words that you share with no one is safest.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Text code, app code, passkey · Phishing resistance','A fake sign-in page instantly passes everything you type to the real site. Which method alone stops this attack?','{\"icon\":\"🔑\",\"options\":[{\"id\":\"s1\",\"text\":\"A one-time code sent by text message\"},{\"id\":\"s2\",\"text\":\"The authenticator app\'s 30-second code\"},{\"id\":\"s3\",\"text\":\"A long, unique password\"},{\"id\":\"s4\",\"text\":\"A passkey tied to the site\'s address\"}]}','{\"choice\":\"s4\"}','Text and authenticator app codes can be typed into the fake page and passed on. A passkey is tied to the real site\'s address and will not sign in on a fake one, so it resists phishing.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Midnight alert flood · Approval fatigue','At 2 a.m. you get 15 sign-in approval requests, then \'IT support\' calls and says: \'Approve just one and we\'ll fix the system.\' What do you do?','{\"icon\":\"📱\",\"options\":[{\"id\":\"s1\",\"text\":\"I approve one so the alerts stop, then change my password\"},{\"id\":\"s2\",\"text\":\"I approve none, change my password and report it to the security team through the official channel\"},{\"id\":\"s3\",\"text\":\"I tell the caller I declined them all and do nothing else\"},{\"id\":\"s4\",\"text\":\"I mute the alerts and look at them when I get to work\"}]}','{\"choice\":\"s2\"}','The requests mean an attacker has your password; the call is a trick to get your approval. Don\'t approve, change your password and report it to the security team through the official channel you know.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Complex-looking pattern · Password strength','Which one best resists an offline guessing attack? (All are examples.)','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"London2024!\"},{\"id\":\"s2\",\"text\":\"P@ssw0rd#2026\"},{\"id\":\"s3\",\"text\":\"lantern dove scythe cloud\"},{\"id\":\"s4\",\"text\":\"L0nd0n!!2024Uk\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password.\",\"password_test\":true}','{\"choice\":\"s3\"}','\'City + year + !\' and letter-to-symbol swaps are the first patterns in attackers\' word rules. Four randomly chosen words are far stronger than passwords that only look complex.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Unused recovery address · Account recovery','Your main email\'s recovery address is on your old company\'s domain, which has expired. Two-step verification is on. What is the right risk assessment?','{\"icon\":\"🛡️\",\"options\":[{\"id\":\"s1\",\"text\":\"Two-step verification is on, so the recovery address doesn\'t matter\"},{\"id\":\"s2\",\"text\":\"No risk; the company closed, so the address can\'t be used\"},{\"id\":\"s3\",\"text\":\"Just making the main password longer removes this risk\"},{\"id\":\"s4\",\"text\":\"Someone could take over the domain; I should change the recovery address and save recovery codes\"}]}','{\"choice\":\"s4\"}','Someone can buy an expired domain and create that address, and account recovery can get around two-step verification. Change the recovery address to one you control and keep recovery codes safe.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (4,'password','Short and complex, or long and simple · Length','Which one holds out against an attacker the longest?','{\"icon\":\"🔐\",\"options\":[{\"id\":\"s1\",\"text\":\"Tr#9kL!2\"},{\"id\":\"s2\",\"text\":\"Brooklyn34!Brooklyn34!\"},{\"id\":\"s3\",\"text\":\"rabbit-lantern-cloud-corn-rock\"},{\"id\":\"s4\",\"text\":\"P@ssw0rd2026#\"}],\"interaction_hint\":\"Example passwords are made up; never type your real password anywhere.\",\"password_test\":true}','{\"choice\":\"s3\"}','Five random words take far longer to crack than an 8-character complex password. Typing the same part twice adds no real length; attackers try repeats too.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Delivery Message','What should Alex do?','{\"post\":\"Alex posts on social media about his latest order. Right after, he gets a message asking for his card details.\",\"author\":\"Alex\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 03\",\"options\":[{\"id\":\"a\",\"text\":\"Send his card details\"},{\"id\":\"b\",\"text\":\"Open the link in the message right away\"},{\"id\":\"c\",\"text\":\"Check with the company through its official channel\"}]}','{\"choice\":\"c\"}','Scammers can use public posts to make messages look personal. Check with the company through its official channel.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','New Follower','What should she do?','{\"post\":\"Mira sees a request for private information sent to her from an account she doesn\'t know.\",\"author\":\"Mira\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 06\",\"options\":[{\"id\":\"a\",\"text\":\"Send her personal details\"},{\"id\":\"b\",\"text\":\"Share her password\"},{\"id\":\"c\",\"text\":\"Give no information without checking the request\"}]}','{\"choice\":\"c\"}','Never send sensitive information to an account whose identity you can\'t confirm.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Personal Quiz','Which decision is safe?','{\"post\":\"A fun quiz on social media asks for your childhood address and your mother\'s maiden name.\",\"author\":\"Alex\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 09\",\"options\":[{\"id\":\"a\",\"text\":\"Writing the answers publicly\"},{\"id\":\"b\",\"text\":\"Giving the details to an app that collects them\"},{\"id\":\"c\",\"text\":\"Not sharing private details\"}]}','{\"choice\":\"c\"}','Some of these questions are also used to recover accounts, so the answers can help someone break in.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Tag Request','Which is the safer choice?','{\"post\":\"A stranger asks you to tag people connected to your profile.\",\"author\":\"Ava\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 12\",\"options\":[{\"id\":\"a\",\"text\":\"Tagging everyone\"},{\"id\":\"b\",\"text\":\"Sending a list of contacts\"},{\"id\":\"c\",\"text\":\"Refusing; not showing a stranger the people around you\"}]}','{\"choice\":\"c\"}','A stranger asking for the people around you may use them to send more fake messages. Refuse the request, and block and report the account if needed.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','AI Voice Message','What is the right step?','{\"post\":\"A voice that sounds like a family member asks for money urgently and tells you not to tell anyone.\",\"author\":\"Alex\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 15\",\"options\":[{\"id\":\"a\",\"text\":\"Send it right away\"},{\"id\":\"b\",\"text\":\"Call back on a known number and check with something only you both know\"},{\"id\":\"c\",\"text\":\"Share ID details too\"}]}','{\"choice\":\"b\"}','AI tools can make faking a voice easy. When there is pressure to hurry and keep it secret, check through a separate channel.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Quiz App','How should you decide?','{\"post\":\"A personality quiz asks for access to your contacts, location and microphone all at once.\",\"author\":\"Ava\",\"handle\":\"@example_profile\",\"chapter\":\"Digital Footprint / 18\",\"options\":[{\"id\":\"a\",\"text\":\"Allow them all\"},{\"id\":\"b\",\"text\":\"Compare the permissions with what the app does and refuse the unneeded ones\"},{\"id\":\"c\",\"text\":\"Upload your friends\' details\"}]}','{\"choice\":\"b\"}','Permissions should match what the app actually does. Refuse access it doesn\'t need, and consider not using the app at all.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','New job post · 14','Which step is right?','{\"author\":\"Ethan\",\"handle\":\"@ethan_example\",\"post\":\"Ethan is about to share a photo for his new job; his staff badge number can be read in it.\",\"options\":[{\"id\":\"s3\",\"text\":\"Share a photo where the badge isn\'t visible at all\"},{\"id\":\"s2\",\"text\":\"Upload both sides of the badge\"},{\"id\":\"s4\",\"text\":\"Cover only the badge number and share\"},{\"id\":\"s1\",\"text\":\"Post his login details\"}],\"story_type\":\"tek_adimli_senaryo\",\"share_mode\":\"draft\"}','{\"choice\":\"s3\"}','A staff badge shows a photo, name, number and barcode together; someone could copy it or use it to get into the building. Hiding only the number is not enough. Share without showing the badge at all.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','GitHub screenshot · 16','What is the safest move here?','{\"author\":\"Ben\",\"handle\":\"@ben_example\",\"post\":\"Ben accidentally shows an API key (a secret access key) in a screenshot of his code.\",\"options\":[{\"id\":\"s3\",\"text\":\"Just delete the photo\"},{\"id\":\"s1\",\"text\":\"Cancel and replace the key, and remove the image\"},{\"id\":\"s2\",\"text\":\"Write the key in the caption\"}],\"story_type\":\"tek_adimli_senaryo\"}','{\"choice\":\"s1\"}','A secret key that was exposed must be replaced, even if the post is deleted, because someone may already have copied it.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Meeting link · 17','What is the safest approach?','{\"author\":\"Alice\",\"handle\":\"@alice_example\",\"post\":\"Alice adds the invite link for a private meeting to a public post.\",\"options\":[{\"id\":\"s3\",\"text\":\"Remove the link from the post, create a new one and send it only to invited people\"},{\"id\":\"s2\",\"text\":\"Leave it public\"},{\"id\":\"s4\",\"text\":\"Just deleting the post is enough; keep using the same link\"},{\"id\":\"s1\",\"text\":\"Post the meeting code separately\"}],\"story_type\":\"tek_adimli_senaryo\"}','{\"choice\":\"s3\"}','A link shared publicly may already be in other people\'s hands; deleting the post doesn\'t undo that. Remove the link, create a new link or password for the meeting, and send it only to invited people.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Fake help request · 20','What is the safest behaviour?','{\"author\":\"Harold\",\"handle\":\"@harold_example\",\"post\":\"Harold gets an unexpected message from a relative\'s account asking for money.\",\"options\":[{\"id\":\"s3\",\"text\":\"Check by calling the person on a known number\"},{\"id\":\"s1\",\"text\":\"Send a bank transfer right away\"},{\"id\":\"s2\",\"text\":\"Enter card details on the link in the message\"}],\"story_type\":\"tek_adimli_senaryo\"}','{\"choice\":\"s3\"}','Remember that accounts of people you know can be taken over too. Check by calling them on a number you already know.','50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','School badge · School name','What should Daisy do before posting the photo?','{\"author\":\"Daisy\",\"handle\":\"@daisy_draws\",\"post\":\"Daisy took a mirror selfie in her new school uniform. The school\'s name and badge are big and clear on the chest. She wants to post it on her public account with the caption \'First day!\'.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Post it; everyone knows the school name anyway\"},{\"id\":\"s2\",\"text\":\"Turn off the location tag and post the photo as it is\"},{\"id\":\"s3\",\"text\":\"Pick a photo where the badge doesn\'t show, or send it only to her family\"},{\"id\":\"s4\",\"text\":\"Write the school name in the caption too, so friends can find her\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s3\"}','The school name on the uniform tells a stranger where to find you every day. Turning off location isn\'t enough, because the clue is in the photo. Pick a shot that hides the school, or share it only with people you know.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Nearby players · Game location','What should Kevin do?','{\"author\":\"Kevin\",\"handle\":\"@kevin_blocks\",\"post\":\"Kevin\'s map game has a feature called \'See players near you\'. When it\'s on, the game shows other players how many metres they are from Kevin\'s home. His friends say: \'Turn it on so we can find each other.\'\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Turn the feature off and check the game\'s location settings with a grown-up\"},{\"id\":\"s2\",\"text\":\"Turn it on only after school and off at home\"},{\"id\":\"s3\",\"text\":\"Leave it on but change his nickname in the game\"},{\"id\":\"s4\",\"text\":\"Turn it on, because everyone in the game is a kid he knows\"}]}','{\"choice\":\"s1\"}','Live location lets anyone in the game find you in real life, and you can\'t know who a player really is. Changing your nickname doesn\'t hide your location. Turn off location sharing and check the settings with an adult you trust.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Secret photo request · Stranger','What should Zoe do?','{\"author\":\"Zoe\",\"handle\":\"@zoe_pencil\",\"post\":\"In a game chat, someone Zoe doesn\'t know writes: \'You play so well! Can you send me a photo of you? I\'ll send you game coins in return. Don\'t tell anyone, it\'s our secret.\'\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Send a photo where her face doesn\'t show\"},{\"id\":\"s2\",\"text\":\"Ask for their photo first, and send hers if they\'re really a kid\"},{\"id\":\"s3\",\"text\":\"Delete the chat and tell nobody what happened\"},{\"id\":\"s4\",\"text\":\"Not reply, keep the message, and tell a trusted adult right away\"}]}','{\"choice\":\"s4\"}','A stranger asking for a photo, offering a gift and saying \'it\'s a secret\' are all danger signs together. Send no photo and don\'t delete the chat, because adults may need those messages to report it. Tell your family or teacher right away; you did nothing wrong.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','A friend\'s message · Screenshot','What should Charlie do?','{\"author\":\"Charlie\",\"handle\":\"@charlie_rocket\",\"post\":\"Charlie\'s friend Max wrote in a private message that he got a low grade on a test and is really upset. Charlie is thinking of posting a screenshot of it in the class group chat with \'So funny!\'.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Scribble out Max\'s name and post the screenshot like that\"},{\"id\":\"s2\",\"text\":\"Not share the screenshot; the private message belongs to Max. Support Max instead\"},{\"id\":\"s3\",\"text\":\"Send it only to his three closest friends\"},{\"id\":\"s4\",\"text\":\"Post it in his story; it disappears after 24 hours anyway\"}]}','{\"choice\":\"s2\"}','A private message was written by someone who trusted you; once a screenshot is sent it can\'t be taken back, and others can save it. Scribbling out the name doesn\'t help when the whole class knows everyone. Don\'t share someone\'s message without their permission.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','After the concert · Delayed post','What is the best judgement of Ella\'s plan?','{\"author\":\"Ella\",\"handle\":\"@ella_onstage\",\"post\":\"Ella went to a concert at the weekend. She will post the photos after she gets home, not during the concert. As the location tag she will write only the city name; her profile shows no school or home details.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Risky; concert photos should never be posted\"},{\"id\":\"s2\",\"text\":\"Better to post live at the concert; nobody can find her in the crowd\"},{\"id\":\"s3\",\"text\":\"The post is dangerous unless the city name is removed too\"},{\"id\":\"s4\",\"text\":\"Reasonable; a delayed post and a general location don\'t let anyone find her in the moment\"}],\"share_mode\":\"draft_safe\"}','{\"choice\":\"s4\"}','This time the plan is safe: Ella posts after she has left and gives only a general location. The risk comes from sharing a live, detailed location. Controlling timing and detail is enough; there\'s no need to ban every post.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Exam entry slip · Photo','What should Owen share?','{\"author\":\"Owen\",\"handle\":\"@owen_goals\",\"post\":\"The day before a big exam, Owen wants to post a photo of his exam entry slip with \'Big day tomorrow!\'. The slip shows his name, national ID number, photo, exam room and a barcode.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Post the slip but scribble out only the ID number\"},{\"id\":\"s2\",\"text\":\"Post a photo of the exam building or his study desk instead of the slip\"},{\"id\":\"s3\",\"text\":\"Post the slip only to his close friends list\"},{\"id\":\"s4\",\"text\":\"Post the slip after the exam, when it\'s no longer useful\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s2\"}','The entry slip shows an ID number, barcode and personal details together; these can be used to pretend to be him or for fake \'check your results\' traps. Scribbling one field leaves the barcode and the rest, and the details stay valid after the exam. Share the excitement without the slip.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','New house key · Photo','What is the best step before posting?','{\"author\":\"Mark\",\"handle\":\"@mark_newhome\",\"post\":\"Mark took a photo holding the key to his new home in front of the door and wants to post it with \'Finally ours!\'. The key\'s teeth are sharp and close up, and the door number is visible behind.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Post the photo to friends only\"},{\"id\":\"s2\",\"text\":\"Pick a shot where the key\'s teeth and the door number don\'t show\"},{\"id\":\"s3\",\"text\":\"Crop out the door number and leave the key as it is\"},{\"id\":\"s4\",\"text\":\"As long as there\'s no location tag, the post is safe\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s2\"}','A sharp photo of a key can be enough to cut a copy from its teeth, and the door number shows which door it opens. Hiding only one of them doesn\'t remove the risk. Share the joy with a shot that shows neither the key nor the address.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Morning check-in · Routine','What is the best advice for Beth?','{\"author\":\"Beth\",\"handle\":\"@beth_mornings\",\"post\":\"For three months, Beth has checked in at the same gym at 6:45 every morning, then written \'Off to work!\'. Her profile is public and her posts can be read in date order.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Making her profile private is enough on its own\"},{\"id\":\"s2\",\"text\":\"Keep checking in but don\'t show the time\"},{\"id\":\"s3\",\"text\":\"Stop live check-ins; if she posts, do it after leaving the gym and at irregular times\"},{\"id\":\"s4\",\"text\":\"Post only on weekdays, so nobody can tell she\'s home at weekends\"}]}','{\"choice\":\"s3\"}','Check-ins that look harmless one by one turn into a timetable that shows when the home is empty and where she will be. A private profile is only as safe as its follower list. Dropping live check-ins and posting later breaks the pattern.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Location data · 18','Which check makes sense?','{\"author\":\"Tom\",\"handle\":\"@tom_example\",\"post\":\"Tom isn\'t sure whether the photo he is about to post contains location information.\",\"options\":[{\"id\":\"s1\",\"text\":\"Check the photo\'s hidden location data and the sharing settings\"},{\"id\":\"s2\",\"text\":\"Make the location tag bigger\"},{\"id\":\"s3\",\"text\":\"Add the address\"}],\"story_type\":\"tek_adimli_senaryo\",\"share_mode\":\"draft\"}','{\"choice\":\"s1\"}','Some photos or sharing platforms can carry hidden location information. Check it before you post.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Room tour trend · Background','What should Sophie check before posting the video?','{\"author\":\"Sophie\",\"handle\":\"@sophie_diary\",\"post\":\"Sophie filmed a video for the viral \'Room tour\' trend. It shows the sign on the building opposite through the window, her school timetable on the wall, and a parcel on the desk with her address on it.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"The video is short, so nobody will notice details\"},{\"id\":\"s2\",\"text\":\"Blurring only the address on the parcel is enough\"},{\"id\":\"s3\",\"text\":\"Remove home and routine clues like the window view, timetable and address label, then film again\"},{\"id\":\"s4\",\"text\":\"If she posts at midnight instead of right after filming, the clues stop mattering\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s3\"}','Trends push people to post fast, and a video can be paused frame by frame. Hiding one clue isn\'t enough: the view shows the building and the timetable shows her hours. Watch the video as a stranger would before posting and remove every clue.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Cartoon quiz · Security questions','What is the best decision about this quiz?','{\"author\":\"Billy\",\"handle\":\"@billy_reads\",\"post\":\"A \'Which cartoon character are you?\' quiz is going round Billy\'s feed. Questions: Your first pet\'s name? The city you were born in? Your first teacher\'s name? Your favourite colour? To see the result, you must write your answers in the comments.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Not answer; these are the same as account recovery security questions\"},{\"id\":\"s2\",\"text\":\"Answer only the favourite colour question and skip the rest\"},{\"id\":\"s3\",\"text\":\"Enter the answers on the quiz\'s own site instead of the comments\"},{\"id\":\"s4\",\"text\":\"If everyone\'s joining in, it\'s fine; answer for fun\"}]}','{\"choice\":\"s1\"}','First pet\'s name, birthplace and teacher\'s name are exactly the security questions used to recover accounts. Writing them in comments or on an unknown site hands them to whoever collects them. Skip the quiz; for security questions use random answers only you know, not the truth.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Video call threat · Blackmail','What should Ben do now?','{\"author\":\"Ben\",\"handle\":\"@ben_runs\",\"post\":\"Ben had a video call with someone he met online. Now that person threatens to send an embarrassing screenshot of Ben to his friends and demands money within an hour.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Send the money; the other person promises to delete the image\"},{\"id\":\"s2\",\"text\":\"Not pay, delete all the messages and close his account right away\"},{\"id\":\"s3\",\"text\":\"Keep talking to calm them down and try to bargain\"},{\"id\":\"s4\",\"text\":\"Not pay, stop replying, save the messages, tell a trusted adult and report the account\"}]}','{\"choice\":\"s4\"}','Paying doesn\'t end blackmail; it usually leads to more demands. Deleting messages destroys the evidence needed to report it. Stop replying, keep the evidence, tell a trusted adult and report to the platform and the police; the shame belongs to the blackmailer, not you.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Reflection in the glass · Office selfie','What should he do before posting the photo?','{\"author\":\"Tom\",\"handle\":\"@tom_atwork\",\"post\":\"Tom took a selfie at his desk in the office. The glass partition behind him reflects his monitor, and the customer list can be read. A sticky note on the edge of the screen shows the guest Wi-Fi password.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Blur the sticky note; the rest is fine\"},{\"id\":\"s2\",\"text\":\"Zoom in and scan the reflections and background; retake a shot where the screen and password don\'t show\"},{\"id\":\"s3\",\"text\":\"Make the photo black and white so details can\'t be read\"},{\"id\":\"s4\",\"text\":\"Post it only in a closed group with his coworkers\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s2\"}','Reflections and background details can be read when a high-resolution photo is zoomed in; hiding only the note doesn\'t protect customer data. Filters or closed groups don\'t stop screenshots. Zoom in and scan the shot before posting, and retake it with the screen off if needed.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Urgent warning chain · Fact-check','What should Grace do with this message?','{\"author\":\"Grace\",\"handle\":\"@grace_news\",\"post\":\"A message in the neighbourhood group: \'BREAKING! Chemicals got into the tap water, don\'t drink it, forward to everyone!\' Below it is a photo of a flooded street. There is no source, date or agency name.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Forward it just in case; even if it\'s false, it harms no one\"},{\"id\":\"s2\",\"text\":\"Forward it with a note saying \'not confirmed\'\"},{\"id\":\"s3\",\"text\":\"Before forwarding, check official channels and search the photo with a reverse image search to see its date\"},{\"id\":\"s4\",\"text\":\"Accept the news is true because the photo looks real\"}]}','{\"choice\":\"s3\"}','Urgency and no source or date are typical signs of false information; old photos or ones from elsewhere are often passed around as new events. Even adding \'unverified\' still spreads it and grows the panic. First check the official source and when the photo was first published.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','First school day video · A child\'s footprint','What is the most balanced choice for Paula?','{\"author\":\"Paula\",\"handle\":\"@paula_mom\",\"post\":\"Paula wants to post a video of her 6-year-old son crying on his first day of school on her public account. The caption gives his full name, the school\'s name and his birth date.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"If she makes her profile private, she can share everything\"},{\"id\":\"s2\",\"text\":\"Remove only the birth date and post the video\"},{\"id\":\"s3\",\"text\":\"Remove only the school name and post it publicly\"},{\"id\":\"s4\",\"text\":\"Remove identifying details, pick a moment that isn\'t embarrassing and share only with close family\"}],\"share_mode\":\"draft\"}','{\"choice\":\"s4\"}','A child\'s full name, school and birth date together create a lasting digital footprint that can later feed identity fraud and bullying. A video of him crying may be something he wouldn\'t agree to when he\'s older. Remove identifying details, narrow the audience and think about how he\'ll feel later.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Nephew\'s urgent call · Hijacked account','What should Nancy do?','{\"author\":\"Nancy\",\"handle\":\"@nancy_garden\",\"post\":\"A public post from the account of Nancy\'s nephew Ethan: \'I had an accident and my phone is broken! I need an urgent payment at the hospital, send money to this IBAN / bank account number, please share!\' In the comments, many people she knows wrote \'Get well soon\'.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Call Ethan or his family on a number she knows to check; not share the post or send money\"},{\"id\":\"s2\",\"text\":\"Send a small amount; if it\'s a lie, the loss is small\"},{\"id\":\"s3\",\"text\":\"Share the post so more people can help\"},{\"id\":\"s4\",\"text\":\"Comment under the post and ask Ethan if it\'s really him\"}]}','{\"choice\":\"s1\"}','If the account was taken over, replies in posts and comments may come from the scammer too, so asking the same account proves nothing. Urgency and someone else\'s bank account are typical signs. Call your relative or their family on a number you already know, don\'t share the post and report it to the platform.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Pension screenshot · Chain message','What is the right thing for Henry to do?','{\"author\":\"Henry\",\"handle\":\"@henry_retired\",\"post\":\"A chain message in a retirees\' group: \'Extra payment has started! To show you qualify, send a screenshot of the pension screen in your banking app to this number and forward this message to 10 people.\' Henry\'s screen shows his account number and balance.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Scribble out the account number and send the screenshot\"},{\"id\":\"s2\",\"text\":\"Not send the screenshot or forward the message; check the payment through the official agency\'s own channel\"},{\"id\":\"s3\",\"text\":\"Not send the screenshot, but forward the message to 10 people\"},{\"id\":\"s4\",\"text\":\"First see whether other retirees in the group sent theirs\"}]}','{\"choice\":\"s2\"}','Real payments never require sending a screenshot of your banking app to a phone number or forwarding a message. The name, account and balance in the screenshot are used for targeted scam calls, and forwarding spreads the trap. Check payments only through the agency\'s official channel.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Harmless pieces · Profile building','What risk do these posts create together?','{\"author\":\"Kyle\",\"handle\":\"@kyle_memories\",\"post\":\"Kyle\'s posts from the past year: his dog Snowball\'s birthday, a memory from the town where he was born, 15 years since his high school graduation, a celebration tagging his mother with her maiden name, and the name of his new workplace.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Each post is harmless alone, so there\'s no extra risk\"},{\"id\":\"s2\",\"text\":\"Put together, they give a full profile for security question answers and convincing targeted phishing\"},{\"id\":\"s3\",\"text\":\"The risk only exists if the posts have location tags\"},{\"id\":\"s4\",\"text\":\"The risk is limited to the workplace name; deleting it is enough\"}]}','{\"choice\":\"s2\"}','Attackers combine small pieces from public sources to answer account recovery questions and write convincing personal messages. Deleting one detail doesn\'t break up the profile. Review old posts, narrow your audiences and use random answers, not real facts, for security questions.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Uncle\'s video · Fake video','What is Laura\'s best step?','{\"author\":\"Laura\",\"handle\":\"@laura_family\",\"post\":\"A video is spreading in the family group in which Laura\'s uncle urges people to invest in a cryptocurrency. The voice and face look very like him, but his lips don\'t quite match the words. The video has been shared thousands of times in other groups.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"Call her uncle on a number she knows to check; report it to the platform without forwarding and briefly warn the family\"},{\"id\":\"s2\",\"text\":\"Post the video on her own account with \'This is fake!\' so everyone sees\"},{\"id\":\"s3\",\"text\":\"Accept it as real because the voice sounds like her uncle\"},{\"id\":\"s4\",\"text\":\"Download the video, send it to her uncle and ask him to post an explanation\"}]}','{\"choice\":\"s1\"}','Voices and faces can now be cloned from a few seconds of recording; lips not matching the words and an unusual money request are key signs. Even reposting it with a \'fake\' note spreads the video further. Check with the person through a known channel, report the content and warn the family without forwarding it.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','New finance manager · Job announcement','What is the best judgement about this post?','{\"author\":\"Sean\",\"handle\":\"@sean_finance\",\"post\":\"Sean posted on his professional network: \'Today I started as finance manager at my new company! Thanks to our CEO Alison and our payments team.\' The post tags the team members\' names and the supplier system they use.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"It\'s a professional network, so the post is completely risk-free\"},{\"id\":\"s2\",\"text\":\"The only risk is that his old employer might be upset\"},{\"id\":\"s3\",\"text\":\"The post helps scammers pretend to be managers; he should share fewer details and check urgent payment requests through a known channel\"},{\"id\":\"s4\",\"text\":\"If he deletes the post, the risk is fully gone and nothing else is needed\"}]}','{\"choice\":\"s3\"}','New finance staff don\'t yet know company processes, so they are targets for \'urgent, secret payment from the CEO\' requests; names and supplier details make these messages believable. A deleted post may already be copied. Limit the details and confirm every payment request through a channel you already know.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (5,'story','Sunset without location · Metadata','What is the best judgement about this post?','{\"author\":\"Megan\",\"handle\":\"@megan_coast\",\"post\":\"Megan is about to post a sunset photo she took last week on a public beach. On the sharing screen, \'Include location\' is off, and she checked with a metadata viewer that the GPS field is empty. The shot shows only sea and sky.\",\"story_type\":\"tek_adimli_senaryo\",\"options\":[{\"id\":\"s1\",\"text\":\"She shouldn\'t post; platforms always restore deleted location data\"},{\"id\":\"s2\",\"text\":\"Post only to close friends; a public photo is always risky\"},{\"id\":\"s3\",\"text\":\"Take a screenshot first and post that; the original file is never safe\"},{\"id\":\"s4\",\"text\":\"She can post it; the location data is removed, nothing in the shot identifies her, and the post is delayed\"}],\"share_mode\":\"draft_safe\"}','{\"choice\":\"s4\"}','The right checks are done: the GPS data was removed and confirmed, the photo has no home or routine clues, and it is posted after the event. Extra steps wouldn\'t hurt but aren\'t needed. Safe sharing means doing the right checks, not banning everything.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 3','You are done on a shared computer. What now?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"opt0\",\"text\":\"Leave the browser open\"},{\"id\":\"opt1\",\"text\":\"Sign out of your account\"},{\"id\":\"opt2\",\"text\":\"Save your password\"},{\"id\":\"opt3\",\"text\":\"Share the session\"}]}','{\"choice\":\"opt1\"}','Always sign out on shared devices.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 6','You found a USB stick you don\'t know. What do you do?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"Plug it into the computer\"},{\"id\":\"opt1\",\"text\":\"Give it to a friend to check\"},{\"id\":\"opt2\",\"text\":\"Don\'t plug it in; tell a staff member\"},{\"id\":\"opt3\",\"text\":\"Format it and use it\"}]}','{\"choice\":\"opt2\"}','Unknown USB sticks can carry risks.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 9','Which is true about AI-generated images?','{\"category\":\"Web Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"You can always tell\"},{\"id\":\"opt1\",\"text\":\"They always have mistakes\"},{\"id\":\"opt2\",\"text\":\"They can always be told apart from photos\"},{\"id\":\"opt3\",\"text\":\"Just looking at the image may not be enough\"}]}','{\"choice\":\"opt3\"}','Checking where an image came from is often more reliable than studying how it looks.','14-18,19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 12','If a website uses HTTPS...','{\"category\":\"Web Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"It is definitely trustworthy\"},{\"id\":\"opt1\",\"text\":\"There can never be a scam\"},{\"id\":\"opt2\",\"text\":\"The connection may be encrypted, but the site still needs checking\"},{\"id\":\"opt3\",\"text\":\"You can share any information\"}]}','{\"choice\":\"opt2\"}','HTTPS alone does not guarantee that a website is trustworthy.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 15','What can you do if you see cyberbullying?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"opt0\",\"text\":\"Join in\"},{\"id\":\"opt1\",\"text\":\"You have to ignore it\"},{\"id\":\"opt2\",\"text\":\"Spread it to everyone\"},{\"id\":\"opt3\",\"text\":\"Ask a trusted adult or a support service for help\"}]}','{\"choice\":\"opt3\"}','Reporting safely and getting support matter.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 18','Why should you use a screen lock?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"For decoration\"},{\"id\":\"opt1\",\"text\":\"For better photos\"},{\"id\":\"opt2\",\"text\":\"To limit access by others without permission\"},{\"id\":\"opt3\",\"text\":\"For Wi-Fi\"}]}','{\"choice\":\"opt2\"}','A lock screen makes it harder for someone to use your device without permission.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 21','What is a digital footprint?','{\"category\":\"Web Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"The traces of information and activity you leave online\"},{\"id\":\"opt1\",\"text\":\"Your shoe size\"},{\"id\":\"opt2\",\"text\":\"The colour of your IP address\"},{\"id\":\"opt3\",\"text\":\"Your computer\'s brand\"}]}','{\"choice\":\"opt0\"}','What we do online can leave all kinds of information behind.','14-18,19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 24','What does a lookalike-domain (homograph) attack use?','{\"category\":\"Scams\",\"options\":[{\"id\":\"opt0\",\"text\":\"Similar-looking characters to build a fake address\"},{\"id\":\"opt1\",\"text\":\"Making Wi-Fi faster\"},{\"id\":\"opt2\",\"text\":\"File compression\"},{\"id\":\"opt3\",\"text\":\"Screen brightness\"}]}','{\"choice\":\"opt0\"}','Attackers can use similar-looking letters from other alphabets to make web addresses that look like the real one. Read the address carefully.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 27','Why should app updates come from the official store or the maker?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"opt0\",\"text\":\"So the file is more colourful\"},{\"id\":\"opt1\",\"text\":\"To lower the risk of malware disguised as an update\"},{\"id\":\"opt2\",\"text\":\"To make your password shorter\"},{\"id\":\"opt3\",\"text\":\"To see ads\"}]}','{\"choice\":\"opt1\"}','Instead of a random link in an update message, use your device settings, the official store or the maker\'s website.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 30','Which is true about a passkey?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"It is the same text password on every site\"},{\"id\":\"opt1\",\"text\":\"It uses a key on your device tied to the real website, so it can resist phishing better\"},{\"id\":\"opt2\",\"text\":\"It always works through SMS\"},{\"id\":\"opt3\",\"text\":\"It should be shared with friends\"}]}','{\"choice\":\"opt1\"}','A passkey\'s secret key never leaves your device, and it only works on the real website it was made for.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 33','A file is named “invoice.pdf.exe”. What should you think?','{\"category\":\"Web Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"That it is just a PDF\"},{\"id\":\"opt1\",\"text\":\"That the double extension may hide a program file\"},{\"id\":\"opt2\",\"text\":\"That it is definitely safe\"},{\"id\":\"opt3\",\"text\":\"That it needs to be printed\"}]}','{\"choice\":\"opt1\"}','Keep file extensions visible and don\'t open unexpected program files. Check with the sender another way.','14-18,19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Knowledge Arena 36','What does the principle of least privilege mean?','{\"category\":\"Workplace Security\",\"options\":[{\"id\":\"opt0\",\"text\":\"Giving everyone admin rights\"},{\"id\":\"opt1\",\"text\":\"Giving people and apps only the access they need\"},{\"id\":\"opt2\",\"text\":\"Making all files public\"},{\"id\":\"opt3\",\"text\":\"Sharing passwords\"}]}','{\"choice\":\"opt1\"}','Limiting access to what a task needs reduces the damage even if an account is taken over.','all',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','AI output · 14','An AI tool gives you wrong information that sounds certain. What should you do?','{\"category\":\"AI\",\"options\":[{\"id\":\"s1\",\"text\":\"Share it without checking\"},{\"id\":\"s2\",\"text\":\"Check it with independent, reliable sources\"},{\"id\":\"s3\",\"text\":\"Accept it as true\"}]}','{\"choice\":\"s2\"}','AI tools can sound confident and still give wrong information.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Cloud sharing · 16','A confidential file will be shared in the cloud. Which setting is best?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"s2\",\"text\":\"Anyone can access it\"},{\"id\":\"s3\",\"text\":\"Visible to search engines\"},{\"id\":\"s1\",\"text\":\"Access only for the people who need it\"}]}','{\"choice\":\"s1\"}','Apply the principle of least privilege to file sharing too.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Reporting an attack · 17','You got a suspicious email at work. What should you do?','{\"category\":\"Workplace Security\",\"options\":[{\"id\":\"s2\",\"text\":\"Report it to the security team through the official channel\"},{\"id\":\"s1\",\"text\":\"Open the attachment to test it\"},{\"id\":\"s3\",\"text\":\"Forward it to everyone\"}]}','{\"choice\":\"s2\"}','Suspicious cases should be passed on through your organisation\'s incident reporting process.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Family photo · 20','Your home address and your grandchild\'s school are visible in a photo. Which choice is safer?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"s2\",\"text\":\"Hide the sensitive details and limit who can see it\"},{\"id\":\"s3\",\"text\":\"Make the location tag public\"},{\"id\":\"s1\",\"text\":\"Write the full address in the caption\"}]}','{\"choice\":\"s2\"}','Details in the background of a photo can be personal data too.','50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','You won a tablet alert · Pop-up','While playing a game, a window pops up: “Congratulations, you won a tablet! Type your name and address.” What do you do?','{\"category\":\"Scams\",\"options\":[{\"id\":\"s1\",\"text\":\"I type my address. Maybe I really won.\"},{\"id\":\"s2\",\"text\":\"I close the window, type nothing and show a grown-up.\"},{\"id\":\"s3\",\"text\":\"I send it to my friends so they can win too.\"},{\"id\":\"s4\",\"text\":\"I type only my name first and give my address later.\"}]}','{\"choice\":\"s2\"}','You can\'t win a contest you never entered. These windows are made to get your details or trick your family into paying. Close it without typing anything and tell your family or teacher.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Game update · Official store','Your tablet\'s app store says there is a new update for your favourite game. Which is right?','{\"category\":\"Updates & Backups\",\"options\":[{\"id\":\"s1\",\"text\":\"Updates break the game, so I should never update.\"},{\"id\":\"s2\",\"text\":\"I should download the update separately from a website.\"},{\"id\":\"s3\",\"text\":\"Installing the store update is good; it fixes bugs and security holes.\"},{\"id\":\"s4\",\"text\":\"I should only update if the game gets slow.\"}]}','{\"choice\":\"s3\"}','Updates from the official store fix bugs and security holes that bad people could use. Updating is the right, safe step; if you\'re not sure, ask a grown-up and install it together.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','School finishing time · Game chat','Someone you just met in a game chat asks which school you go to and what time it finishes. What do you do?','{\"category\":\"Privacy\",\"options\":[{\"id\":\"s1\",\"text\":\"I don\'t tell them. I leave the chat and tell a grown-up I trust.\"},{\"id\":\"s2\",\"text\":\"I only tell them the school\'s name, not the time.\"},{\"id\":\"s3\",\"text\":\"If they tell me their school, I\'ll tell them mine.\"},{\"id\":\"s4\",\"text\":\"I tell them in a private message, where nobody else can see.\"}]}','{\"choice\":\"s1\"}','Your school\'s name and finishing time make it easier to find you in real life. Don\'t give them to someone you met online; if they keep asking, block them and tell a grown-up.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Colouring game wants the microphone · Permissions','A colouring game you just downloaded asks to use your microphone when it opens. What is the best choice?','{\"category\":\"Mobile Security\",\"options\":[{\"id\":\"s1\",\"text\":\"I allow it, because I think the game won\'t open otherwise.\"},{\"id\":\"s2\",\"text\":\"I allow both the microphone and the camera so it stops asking.\"},{\"id\":\"s3\",\"text\":\"I delete the game and download another one with the same name from a website.\"},{\"id\":\"s4\",\"text\":\"I tap “Don\'t allow”; if I don\'t know why the game wants it, I ask a grown-up.\"}]}','{\"choice\":\"s4\"}','A colouring game doesn\'t need a microphone to work. Not giving extra permissions stops the app from listening to you; most games work fine without it.','0-13',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Flashlight app wants contacts · Permissions','A flashlight app you downloaded wants access to your contacts, text messages and location. What is the smartest step?','{\"category\":\"Mobile Security\",\"options\":[{\"id\":\"s1\",\"text\":\"I allow everything; it\'s in the app store, so it\'s safe.\"},{\"id\":\"s2\",\"text\":\"I allow only location and deny contacts and texts.\"},{\"id\":\"s3\",\"text\":\"I deny the permissions, delete the app and use my phone\'s own flashlight.\"},{\"id\":\"s4\",\"text\":\"I allow it and take the permissions back in settings a few days later.\"}]}','{\"choice\":\"s3\"}','A flashlight doesn\'t need contacts, texts or location; these requests may be for collecting data or reading SMS verification codes. Data can be taken in the first minute, so remove the app and use your phone\'s built-in flashlight.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Getting ready for account recovery · Social media','If you lose access to your social media account, what helps most to get it back?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"s1\",\"text\":\"Giving my password to my best friend so they can recover it.\"},{\"id\":\"s2\",\"text\":\"Adding no recovery details at all, so nobody can take over the account.\"},{\"id\":\"s3\",\"text\":\"Putting my birthday and school on my profile so the platform recognises me.\"},{\"id\":\"s4\",\"text\":\"Adding an up-to-date recovery email and phone, and keeping backup codes somewhere safe.\"}]}','{\"choice\":\"s4\"}','A recovery email, phone number and backup codes are the fastest way to prove the account is yours. Keeping them up to date now makes getting a hacked account back much easier. Never share backup codes.','14-18',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','How often to change passwords · Current guidance','According to current password security guidance, which is true?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"s1\",\"text\":\"Passwords must be changed every 30 days, even with no sign of a leak.\"},{\"id\":\"s2\",\"text\":\"A short password with capitals, numbers and symbols is always stronger than a long one.\"},{\"id\":\"s3\",\"text\":\"A long password that is unique to each account is key; forced regular changes are not needed unless you suspect it was stolen.\"},{\"id\":\"s4\",\"text\":\"Using one strong password on all accounts is recommended because it is easier to remember.\"}]}','{\"choice\":\"s3\"}','Current guidance does not recommend forcing password changes on a schedule; it leads to small, guessable changes. Change a password if it leaked or may be stolen. Length matters more than complexity rules, and a different password for each account stops one leak from spreading.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Customer spreadsheet and chatbot · Data','To speed up a report, you want to paste a spreadsheet of customer names and phone numbers into a public AI chatbot. What is the right approach?','{\"category\":\"AI\",\"options\":[{\"id\":\"s1\",\"text\":\"I only use the tool my organisation approved and remove or anonymise the personal data.\"},{\"id\":\"s2\",\"text\":\"It\'s fine if I delete the chat history when I\'m done.\"},{\"id\":\"s3\",\"text\":\"So many people use the tool that it must store the data safely.\"},{\"id\":\"s4\",\"text\":\"If I paste the spreadsheet in small pieces, it doesn\'t count as sharing data.\"}]}','{\"choice\":\"s1\"}','Data typed into public AI tools may be stored on the provider\'s servers and, depending on settings, used to train models. That can mean sharing personal data without permission. Use the tool your organisation approved and remove personal details you don\'t need.','19-25,26-30,31-40,41-49,50+',3);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','App permissions · 18','A new app wants access to all your files. What should be done?','{\"category\":\"App Security\",\"options\":[{\"id\":\"s2\",\"text\":\"Allow it right away\"},{\"id\":\"s3\",\"text\":\"Check whether the permission is needed and who made the app\"},{\"id\":\"s1\",\"text\":\"Write your password in the comments\"}]}','{\"choice\":\"s3\"}','App permissions should match what the app actually does.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Paid scholarship offer · Social media post','An account says: “Guaranteed scholarship: pay a $10 application fee, send your password for the official government portal, places fill up today.” Which assessment is right?','{\"category\":\"Scams\",\"options\":[{\"id\":\"s1\",\"text\":\"A fee, a password request and urgency together are signs of a scam; I check the scholarship on the provider\'s official website.\"},{\"id\":\"s2\",\"text\":\"The fee is small, so the risk is low; just not giving the password is enough.\"},{\"id\":\"s3\",\"text\":\"It\'s safe if I send a screenshot of the government portal instead of the password.\"},{\"id\":\"s4\",\"text\":\"If the account sharing it has lots of followers, it can be trusted.\"}]}','{\"choice\":\"s1\"}','Real scholarship providers never ask for your government portal password or promise approval for a fee. A payment request, a login request and “fills up today” pressure together mean it is fake. Apply on the provider\'s official website, which you find yourself.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Two networks with the same name · Fake hotspot','At a cafe you see two open Wi-Fi networks called “Cafe_Guest”; one has a stronger signal. What is the best approach?','{\"category\":\"Network Security\",\"options\":[{\"id\":\"s1\",\"text\":\"I join the stronger one; fake networks usually have a weak signal.\"},{\"id\":\"s2\",\"text\":\"I ask staff which network is real, and use mobile data if I need to log in to my accounts.\"},{\"id\":\"s3\",\"text\":\"I try both and use whichever is faster.\"},{\"id\":\"s4\",\"text\":\"It\'s fine even without a Wi-Fi password, because all websites use HTTPS.\"}]}','{\"choice\":\"s2\"}','Attackers can set up a fake hotspot with the same name as the real one, and it may have a stronger signal. Ask staff which network is real. HTTPS encrypts traffic but won\'t protect what you type into a fake login page. Mobile data is safer for sensitive tasks.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Fake account in your name · Reporting','Someone made a fake account with your name and photo and is posting embarrassing things. What is the best way to handle it?','{\"category\":\"Cyberbullying\",\"options\":[{\"id\":\"s1\",\"text\":\"I block the account right away before saving evidence, so I don\'t see the posts.\"},{\"id\":\"s2\",\"text\":\"I share the posts with my friends so everyone knows the account is fake.\"},{\"id\":\"s3\",\"text\":\"I close my own account; that makes the fake account useless.\"},{\"id\":\"s4\",\"text\":\"I save the links and screenshots, report it to the platform as impersonation, and tell my family or school counsellor.\"}]}','{\"choice\":\"s4\"}','Evidence is needed for reporting to the platform and for any legal steps; after blocking, the posts can be harder to reach. Platforms review impersonation reports separately. Spreading the content makes things worse; an adult\'s support helps.','14-18',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Password typed into a phishing page · First steps','You clicked a link in a work email and typed your work password into the page, then got suspicious. What should you do first?','{\"category\":\"Incident Response\",\"options\":[{\"id\":\"s1\",\"text\":\"I just change my password from the same computer without telling anyone.\"},{\"id\":\"s2\",\"text\":\"I shut down the computer and tell the IT team the next morning.\"},{\"id\":\"s3\",\"text\":\"I open the link again to check whether the page is really fake.\"},{\"id\":\"s4\",\"text\":\"I report it to the IT/security team right away, disconnect the device from the network and change my password from another safe device.\"}]}','{\"choice\":\"s4\"}','Minutes count: the security team can end open sessions and remove the same email from other inboxes. Disconnecting from the network limits any malware; changing the password from a clean device stops the new one being stolen too. Waiting or reopening the link adds risk.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Phone suddenly lost signal · SIM swap','Your phone suddenly shows “No service”, then your email gets “password reset code sent” alerts. What should you do?','{\"category\":\"Mobile Security\",\"options\":[{\"id\":\"s1\",\"text\":\"I restart the phone and wait a few hours for the network to come back.\"},{\"id\":\"s2\",\"text\":\"From another phone I immediately call my mobile carrier and my bank, ask whether my number was moved, and change my passwords.\"},{\"id\":\"s3\",\"text\":\"I click the reset link in the email to cancel the request there.\"},{\"id\":\"s4\",\"text\":\"I take the SIM card out and put it back in; the problem is probably the card.\"}]}','{\"choice\":\"s2\"}','Losing signal at the same time as password reset attempts can mean your number was moved to another SIM card with a fake ID. Calling your mobile carrier to freeze the line stops SMS codes going to the attacker. Later, use an authenticator app or passkey instead of SMS, and ask your carrier for extra SIM checks.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Coupon extension permissions · Browser','While installing, a discount coupon browser extension asks for permission to “Read and change all your data on all websites”. What does this mean?','{\"category\":\"Web Security\",\"options\":[{\"id\":\"s1\",\"text\":\"It can see the content and form entries on every page you open, and change the pages.\"},{\"id\":\"s2\",\"text\":\"It can only see prices on shopping sites; it can\'t reach other pages.\"},{\"id\":\"s3\",\"text\":\"The extension comes from the official store, so this permission is just a technical warning.\"},{\"id\":\"s4\",\"text\":\"This permission only applies on the first day the extension is installed.\"}]}','{\"choice\":\"s1\"}','This broad permission lets the extension read and change every page you open, including online banking and email. Extensions can change owners and get harmful updates later. Don\'t install ones you don\'t need, or limit site access to when you click it or to specific sites.','19-25,26-30,31-40,41-49,50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Panicked call from a grandchild · Voice cloning','Someone who sounds like your grandchild calls: “I had an accident, I need money now, don\'t tell Mom.” The voice is exactly theirs. What is the best step?','{\"category\":\"Scams\",\"options\":[{\"id\":\"s1\",\"text\":\"If it\'s their voice, it\'s definitely them; I send the money without wasting time.\"},{\"id\":\"s2\",\"text\":\"I ask for their birthday; if they know it, it really is my grandchild.\"},{\"id\":\"s3\",\"text\":\"I hang up and call my grandchild or their parents on the saved number, and ask for our family code word.\"},{\"id\":\"s4\",\"text\":\"I send a gift card code instead of money; that\'s safer.\"}]}','{\"choice\":\"s3\"}','AI can copy a person\'s voice from a few seconds of social media video. “Don\'t tell anyone” and rushing you are typical scam signs. A birthday is not proof, as it can be found online. Call back on a number you know; a family code word works well.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Bonus payment message · Pension','An SMS from your bank\'s usual sender name: “Your pension bonus payment has been deposited into your account.” There is no link and nothing is asked of you. What is enough to do?','{\"category\":\"Scams\",\"options\":[{\"id\":\"s1\",\"text\":\"Call the number that sent the message to confirm the amount and verify your card details.\"},{\"id\":\"s2\",\"text\":\"It\'s an information message; if you want, check your account yourself in the bank\'s app or at a branch.\"},{\"id\":\"s3\",\"text\":\"Reply “CONFIRM” to the bank so the payment can be completed.\"},{\"id\":\"s4\",\"text\":\"Every message from a bank is fake; you should close your account right away.\"}]}','{\"choice\":\"s2\"}','An information message with no link, asking for no details, payment or action, about something expected, is not risky on its own. To check, use the number on the back of your card or your bank\'s app, not the number in the message. Your bank never asks for your password or SMS code.','50+',4);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Man-in-the-middle phishing · Passkey vs app codes','An attacker uses a phishing site that sits in the middle and passes everything on to the real login page. Why is a passkey better here than a one-time code from an authenticator app?','{\"category\":\"Account Security\",\"options\":[{\"id\":\"s1\",\"text\":\"A passkey is just a longer password, so it\'s harder to guess.\"},{\"id\":\"s2\",\"text\":\"The one-time code changes every 30 seconds, so it protects as well as a passkey against this attack.\"},{\"id\":\"s3\",\"text\":\"A passkey is tied to the real website and won\'t work on a fake one; a one-time code can be typed into the fake page and passed on.\"},{\"id\":\"s4\",\"text\":\"A passkey encrypts the session cookie, so it can\'t be copied even if the device is hacked.\"}]}','{\"choice\":\"s3\"}','A passkey is tied to the website address it was created for; the browser won\'t sign in on a fake address, so phishing fails. A one-time code can be typed into the fake page and instantly passed to the real site. A passkey can\'t protect session cookies if the device already has malware.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Ransomware and backups · Offline copy','Ransomware has encrypted every drive on the network. Which backup setup gives the most reliable recovery?','{\"category\":\"Updates & Backups\",\"options\":[{\"id\":\"s1\",\"text\":\"An external disk always connected to the computer that backs up automatically every night.\"},{\"id\":\"s2\",\"text\":\"A cloud folder that syncs files instantly, so changes show up right away.\"},{\"id\":\"s3\",\"text\":\"A daily copy kept in a separate folder on the same file server.\"},{\"id\":\"s4\",\"text\":\"A 3-2-1 backup (3 copies, 2 kinds of storage, 1 off-site) with one copy offline or unchangeable, and tested restores.\"}]}','{\"choice\":\"s4\"}','Always-connected disks, instantly synced folders and copies on the same server are within ransomware\'s reach and can be overwritten. An offline copy, or one that can\'t be changed for a set time, gives a recovery point attackers can\'t touch. Test restores regularly, or you can\'t know a backup works.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','What Content Credentials prove · C2PA','A news photo has verified Content Credentials (C2PA). What does this show on its own?','{\"category\":\"AI\",\"options\":[{\"id\":\"s1\",\"text\":\"It proves the event in the photo really happened and the content is true.\"},{\"id\":\"s2\",\"text\":\"It shows who signed it and the recorded edit history; it doesn\'t prove the scene is real.\"},{\"id\":\"s3\",\"text\":\"It proves for certain that the photo was not made with AI.\"},{\"id\":\"s4\",\"text\":\"It proves that photos without credentials are fake.\"}]}','{\"choice\":\"s2\"}','C2PA records, in a tamper-proof way, who signed the content and how it was edited; AI generation can be declared there too. It does not guarantee the signer is honest or the scene is real. Metadata can be removed, so missing credentials alone don\'t prove a fake.','19-25,26-30,31-40,41-49,50+',5);
INSERT INTO questions (game_id,kind,title,prompt,public_json,answer_json,explanation,age_scope,difficulty) VALUES (6,'quiz','Patched security hole · Zero-day and n-day','A vendor patched a security hole and announced it is being actively attacked. Why is it risky to wait for next month\'s planned maintenance?','{\"category\":\"Updates & Backups\",\"options\":[{\"id\":\"s1\",\"text\":\"Once the patch is out, the hole is public; attackers study the patch and quickly target unpatched systems.\"},{\"id\":\"s2\",\"text\":\"There is no risk; once patched it\'s no longer a zero-day and attackers lose interest.\"},{\"id\":\"s3\",\"text\":\"Only zero-day holes are dangerous; antivirus always blocks known holes.\"},{\"id\":\"s4\",\"text\":\"Patches can slow systems down, so waiting a few months is always safer.\"}]}','{\"choice\":\"s1\"}','A zero-day is a hole with no patch yet; once patched it becomes an “n-day”, and attackers can study the patch to build attacks fast. Most real attacks use holes that already have patches, so install patches for actively attacked holes quickly.','19-25,26-30,31-40,41-49,50+',5);
